const PAGE_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>RSDG Bid Builder</title>\n<script src=\"https://unpkg.com/react@18/umd/react.production.min.js\"></script>\n<script src=\"https://unpkg.com/react-dom@18/umd/react-dom.production.min.js\"></script>\n<script src=\"https://unpkg.com/@babel/standalone@7.26.9/babel.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.12.2/mammoth.browser.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js\"></script>\n<style>\n  html, body { margin: 0; padding: 0; background: #eef4f8; }\n  #root { min-height: 100vh; }\n</style>\n</head>\n<body>\n<div id=\"root\"></div>\n<script type=\"text/babel\" data-presets=\"react\">\nconst { useState, useRef, useEffect, Fragment } = React;\n\nfunction Icon({ children, size = 16, style }) {\n  return (\n    <svg width={size} height={size} viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" style={style}>\n      {children}\n    </svg>\n  );\n}\nconst Upload = (p) => <Icon {...p}><path d=\"M12 3v12\" /><path d=\"M7 8l5-5 5 5\" /><path d=\"M4 21h16\" /></Icon>;\nconst X = (p) => <Icon {...p}><path d=\"M18 6 6 18\" /><path d=\"M6 6l12 12\" /></Icon>;\nconst Loader2 = (p) => <Icon {...p}><path d=\"M21 12a9 9 0 1 1-6.219-8.56\" /></Icon>;\nconst Copy = (p) => <Icon {...p}><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" /><path d=\"M5 15V5a2 2 0 0 1 2-2h10\" /></Icon>;\nconst Check = (p) => <Icon {...p}><path d=\"M20 6 9 17l-5-5\" /></Icon>;\nconst Download = (p) => <Icon {...p}><path d=\"M12 3v12\" /><path d=\"M7 12l5 5 5-5\" /><path d=\"M4 21h16\" /></Icon>;\nconst AlertCircle = (p) => <Icon {...p}><circle cx=\"12\" cy=\"12\" r=\"10\" /><path d=\"M12 8v4\" /><path d=\"M12 16h.01\" /></Icon>;\nconst ChevronRight = (p) => <Icon {...p}><path d=\"M9 18l6-6-6-6\" /></Icon>;\nconst ExternalLink = (p) => <Icon {...p}><path d=\"M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6\" /><path d=\"M15 3h6v6\" /><path d=\"M10 14 21 3\" /></Icon>;\n\nconst COLORS = {\n  blue: '#005a91',\n  blueDark: '#00456f',\n  orange: '#fd7504',\n  green: '#20ab21',\n  yellow: '#fed200',\n  white: '#fefefe',\n  ink: '#0f2a3d',\n};\n\nconst RSDG_KNOWLEDGE_BASE = `\nRSDG KNOWLEDGE BASE (verified facts, compiled from the Business Plan 2026-2031 v5,\nSupporting Information document, redrafted CAT Form C, board biographies, and the\nfundraising and marketing strategies)\n\nWHO RSDG IS\nRothes Sports Development Group (RSDG), Scottish Charitable Incorporated Organisation,\ncharity number SC054211, established January 2025. Two-tier SCIO (board of trustees\nplus wider membership). Charitable purposes: advancement of public participation in\nsport, and provision of recreational facilities to improve conditions of life. Vision:\nRothes will be a healthy and happy place where people want to stay, work and have their\nleisure time. Mission: an inclusive, year-round community sports campus bringing\ntogether modern facilities and activity for all ages. Over 300 community members;\nFacebook group of 310 members.\n\nTHE PROJECT\nCommunity ownership (via Community Asset Transfer) of Rothes Recreation Park, Common\nGood land owned by Moray Council, followed by a covered, year-round multi-sport\nfacility on the derelict former bowling green. Three named stages: Project 0\n(~2 years, in parallel with the Community Asset Transfer/Common Good process: surveys,\nplanning, design, legal, funding pipeline; cost £151,860-£175,360); Project 1 (12-month\nbuild year, 6 months construction then 6 months handover/snagging/soft launch; total\ncost £1,550,251 + VAT); Project 2 (operation from opening; trading income covers all\ncosts by Year 3, cumulative surplus ~£164,000 by end of Year 3). Total capital\nrequirement £1.74M-£1.76M + VAT.\n\nSite: grid reference NJ279495, three land areas per Rydens valuation (23 May 2025):\nArea 1 former bowling green (0.879 acre), Area 2 Recreation Park excluding play park\n(2.384 acres), Area 3 adjacent land (1.347 acres). Aggregate valuation £35,000.\nRequesting all three areas at nil consideration under s79(2)(a) Community Empowerment\n(Scotland) Act 2015.\n\nWhat gets built: 2 padel courts (20m x 10m, toughened glass enclosure), 2 pickleball\ncourts, synthetic turf MUGA (31m x 22m, suitable for bowls/tennis/hockey/cricket),\nbasketball court, double barrel vault canopy over all court areas, new pavilion (two\nchanging rooms, a Changing Places Toilet, club room/social space, plant room, storage),\nnew power supply (£25k allowance), EV charging + CCTV (£10k allowance). Built as a\nsingle programme (phasing was considered and rejected: groundworks/foundations must be\nbuilt to full spec regardless, and the canopy is not optional, it's what makes\nyear-round use work in Moray's weather). Existing football pavilion stays; the poor-\ncondition bowling pavilion is replaced.\n\nEVIDENCE OF NEED\nFeasibility study by Community Enterprise (COSS-supported), autumn 2025, mixed methods:\ncommunity survey (191 responses; 84% local residents, 68% from Rothes; 69% aged\n25-64), stakeholder interviews (9 organisations), school engagement (30 pupils, Rothes\nPrimary), community drop-ins (~30 people, Aberlour/Archiestown/Craigellachie/Rothes),\nboard workshops, market analysis, board skills audit, technical survey review.\nHeadline results: 96% support a MUGA; 78% believe it will help people be more active;\n77% would use it (69% at least monthly); 85% already use Recreation Park (70% at least\nmonthly; 65% walking, 25% football); 37% believe it will help the local economy.\nSport interest: padel 58%, pickleball 48%, basketball 43%, badminton 41%. 51% supported\nreplacing the grass pitch with astroturf, which was parked (not pursued) partly on that\nbasis and to preserve green space. An earlier draft referenced 86 survey responses;\nthe finalised, authoritative figure is 191 - always use 191, never 86.\nMarket: astroturf/all-weather pitches regionally oversubscribed, nearest comparable\ncovered provision over an hour away. Comparable community facilities (Methlick,\nAviemore, Strathdearn) sustain 25-35% occupancy; RSDG's own Year 1 assumptions start at\n5-17.5%, deliberately conservative. Confirmed anchor users: Rothes Bowling Club, Rothes\nFC, Rothes Rovers, Aberlour Villa, Dufftown FC, Rothes Primary School, Speyside High\nSchool.\nStrategic fit: SportScotland \"Sport for Life\"; Moray Council physical activity\nframework; Scottish Government Community Wealth Building; Town Centre Regeneration;\nNPF4 20-minute neighbourhoods; Scottish Government Climate Change Plan; Scottish Land\nFund outcomes.\n\nGOVERNANCE AND BOARD\nRestructured at the 2026 AGM after a skills audit; further trustees (incl. one with\ndedicated digital/IT skills) due at the June 2026 AGM.\n- Richard Forsyth, Chairman: born/raised Rothes, Chairman/MD of Forsyths ~40 years,\n  Honorary President of Rothes FC.\n- Peter Scott, Vice Chair: born/raised Rothes (family ties 6 generations), Rothes\n  Tennis Club member since early 1980s.\n- Hamish McBain, Secretary: lived in Rothes all his life, 25 years at Glenrothes\n  Distillery, Secretary of Rothes Tennis Club/Highlands Tennis/Moray Tennis Forum.\n- Maureen Turner, Treasurer: grew up in Rothes (34 years), Rothes Tennis Club trustee,\n  ex-Treasurer Dufftown FC Under-12s, President of the Scottish Association of Painting\n  Craft Teachers.\n- Leigh Anderson: grew up in and raised children in Rothes, years on Rothes Tennis\n  Club committee, ran Rothes Golf Club junior section for a decade.\n- Neal Anderson: born in Rothes, deep family roots, 10 years as Junior Convenor at\n  Rothes Golf Club.\n- Helen Foord: lives in Rothes, runs two digitally-powered marketing agencies (legal\n  sector, UK/international), board member of UHI Moray, registered B Leader (B Corp\n  impact assessment support).\n- Ian Blackhall: trustee, biography not yet provided.\nBoard skills audit (11 areas): strong in project planning, communications, working\nwith people, financial management, governance, leadership, facility management. Gaps:\nmarketing, digital/ICT, business planning, impact evaluation - all four addressed by\nHelen Foord's appointment (the board still wants a dedicated digital/IT trustee too).\nProfessional advisors: Community Enterprise (feasibility/business plan); COSS (CAT\nadvisory); Mac Consulting Landscapes, led by Malcolm Clapperton (site design, cost\nestimate, RIBA Stage 2-6, 20 years' sports design experience incl. Craiglockhart\nTennis Centre, Great Western Golf padel, Hillhead Sports Club, Kinnoull Tennis Club,\nSkipton Tennis Centre, SportScotland Inverclyde, The Grange Club, The Meadows); Hardies\nLLP (building condition surveys); Rydens (land valuation); solicitors (CAT/Common Good\nlegal process).\n\nRELATIONSHIP WITH OTHER ROTHES SPORTS BODIES\nCampus model links four sites: Recreation Park (this project), Mackessack Park\n(Rothes FC, independently developing a full-size synthetic pitch to Scottish FA\nstandards; SFA correspondence confirmed October 2025), Rothes Primary/Speyside High\nSchool, Rothes Tennis Club (own Council lease, adjacent, unaffected by this request).\n\nFINANCE AND FUNDING\nCapital portfolio (~£580k-£1.04M identified against £1.55M+£35k required; MOST OF THIS\nIS NOT SECURED, it is \"application planned\" or \"in discussion\" unless stated\notherwise): Scottish Land Fund £35,000 (land, application mid-2026); Rothes Wind Farm\n£200,000+ across Project 0 and 1 (to be discussed); SportScotland £100,000 (application\nplanned); SSEN Community Benefit Funding £40,000-£500,000 (application planned);\nGarfield Weston Foundation £30,000 (application planned); Peter Harrison Foundation\n£30,000 (application planned); Forsyth Foundation capital tranche £30,000 (relationship\nestablished); Scottish Landfill Communities £25,000 (application planned); Weir\nCharitable Trust £25,000 (application planned); local capital fundraising £25,000\n(ongoing); Barclays Community Sport £20,000 (application planned); CARES £20,000\n(application planned); HIE TBC (in discussion).\nOperating funding for Project 0 (~£152k-£176k over 2 years): Rothes Wind Farm £40,000;\nRobertson Trust £25,000; Foundation Scotland £15,000; Forsyth Foundation £10,000\n(committed in principle); William Grant Foundation £6,000; ScottishPower Foundation\n£5,000; local fundraising £15,000; DO-secured pipeline £5,000. £58,000 was RSDG's\nactual cash reserve at the start of Project 0 (secured/confirmed, not a grant).\nYear 1 operating fundraising target during Project 1 (£140,000): Foundation Scotland\n£25,000; Robertson Trust £25,000; William Grant Foundation £15,000; local campaign\n£15,000; Forsyth Foundation £10,000; ScottishPower Foundation £10,000; DO-secured\npipeline £40,000. This is separate from and additional to the £40,000 Sports\nDevelopment Officer grant and £40,000 revenue start-up grant landing within Year 1.\nFundraising approach: tiered (1-2 lead grants at 15-20% of capital total, 2-4 grants\nat 5-10%, then smaller grants and community appeals). The board will not proceed to\nconstruction until the funding pipeline is sufficient.\nCorporate targets: local distilleries with community investment programmes (Glen\nGrant, Macallan, Cardhu, Craigellachie, Aberlour); Forsyth's (committed in principle);\nconstruction supply chain; regional businesses via Moray Chamber of Commerce.\nCommunity fundraising precedent: Whisky for Rothes charity auction via Just Whisky,\nraised over £33,000; a proposed Inverness-to-Edinburgh charity cycle ride (concept\nstage); planned launch appeal, sponsored events, ceilidhs/quiz nights, individual\ngiving to the 300+ membership, project-based crowdfunding for named elements.\nThree-year operating summary: Year 1 trading income £109,890, total income £189,890,\noverheads £134,982, surplus £54,908. Year 2 trading £129,350, total £184,350, overheads\n£140,016, surplus £44,334. Year 3 trading £168,991, total £208,991, overheads £144,671,\nsurplus £64,320. By Year 3, trading income alone covers all operating costs bar the\nongoing Sports Development Officer grant. Sensitivity: Year 1 absorbs ~50% trading\ndrop, Year 2 ~34%, Year 3 ~38%, and still breaks even.\nPricing: grass pitch and park stay free and open to all. MUGA/pavilion: members\n£15/hour, pay-as-you-play £20/hour, concessions for juniors/over-60s/disabled\npeople/low-income households, schools free at agreed times. Membership 100 (Y1) to\n200 (Y3) at £50/year.\nVAT/water/tax: all costs quoted ex-VAT; RSDG will register early so VAT on\nconstruction (~£298,000) and eligible operating costs is reclaimable. Full exemption\nfrom Scottish Water charges as a charity using premises wholly for charitable\npurposes. Primary purpose trading allowable without corporation tax under OSCR\nguidance.\nLoan contingency: LTA Quick Access Loan Scheme, up to £250,000 interest-free for padel\nfacilities. RSDG qualifies. Held as contingency only; no loan servicing costs modelled.\n\nSTAFFING (Project 2)\nFacilities Manager £38,000 (1.0 FTE); Sports Programme Lead £32,000 (1.0 FTE,\ngrant-funded only, exists only if externally funded); Admin/Finance £28,000 pro rata\n(0.3 FTE); Caretaker/Groundskeeper £26,200 pro rata (0.3 FTE, expands from the TUPE-\ntransferring Council groundskeeper role). Development Officer (Project 0 plus first\n6 months of Project 1): part-time, £1,750/month, dual role of project management and\nfundraising, steps down end of November of Project 1. Facilities Manager joins 3\nmonths pre-opening for a planned handover overlap.\n\nCOMMUNITY BENEFIT TARGETS (first 3 years)\n600 unique users Year 1; 200 school pupils in structured sessions; 150 older adults in\nwalking football/gentle activity/wellbeing; 250 people in environmental\nwalks/volunteering (500+ volunteer hours); 1,000 residents engaged by Year 2 (over a\nfifth of the ~5,000-population AB38 area); 20 trained volunteers within 3 years; 35%\ncourt occupancy by Year 3; self-sustaining on trading income by Year 3.\n\nCAT PROCESS CONTEXT\nForm C route under the Community Empowerment (Scotland) Act 2015. Once submitted and\nacknowledged, Moray Council has 6 months to issue a Decision Notice; a further 6\nmonths to submit the legal offer if accepted; statutory right to internal review then\nappeal to Scottish Ministers if refused. Statutory 8-week public consultation and\ncourt application also apply as this is inalienable Common Good land. Requesting\nownership at nil consideration, justified by the Council's avoided costs, the scale of\nRSDG's committed investment (~£1.7M) against the £35,000 valuation, and the public\nbenefit case.\n`;\n\nconst SYSTEM_PROMPT = `You are helping Rothes Sports Development Group (RSDG) draft answers to a funding application.\n\n${RSDG_KNOWLEDGE_BASE}\n\nGROUND RULES — follow these exactly:\n1. Draft only from facts in the RSDG knowledge base above, or from what's supplied in\n   the form and any uploaded documents for this specific bid. Never invent a\n   statistic, beneficiary number, quote, date, or case study, even a plausible one.\n2. Distinguish secured from planned money. Most named funders in the knowledge base\n   are \"application planned\" or \"in discussion\", not committed. Never present a\n   planned or pipeline funder as if the money is already in hand. Say what's confirmed\n   (e.g. the £58,000 reserve, the Forsyth Foundation relationship, Rothes FC's\n   SFA-confirmed partnership) plainly, and say what's still being sought plainly too.\n3. If a strong answer would need a specific fact that isn't in the knowledge base or\n   this bid's supplied material, write the rest of the answer and insert a clear flag\n   instead of guessing: [NEEDS INPUT: describe exactly what's missing]\n4. If a word or character limit is given for a question, stay within it (land within\n   5% under it, never over). For a character limit, roughly divide by six to estimate\n   a safe word count while drafting.\n5. Before answering anything, run a FIT CHECK. If a funder guidelines document was\n   uploaded, or the form gives enough about the funder's criteria, compare RSDG\n   against it on: organisation type, location, beneficiary group, income/size, and\n   activity type. Say plainly which match and which don't. If a row doesn't match\n   in a way that could make the whole application ineligible (wrong location, wrong\n   org type), say so in one sentence before anything else, then still produce the\n   rest. If there isn't enough information about the funder's criteria to check fit,\n   say so in one line and move on, don't invent criteria to check against.\n6. For each question, first give a brief PLAN (2-4 lines): what the funder is\n   actually trying to find out with this question and how it's likely scored, which\n   specific facts from the knowledge base or this bid's material you'll use, and any\n   gaps you'll need to flag. Then write the ANSWER itself. Label these \"Plan:\" and\n   \"Answer:\" for each question, in the order the funder asked them.\n7. If you've inferred something by connecting two separate pieces of the supplied\n   material, say so briefly at the end of that answer so it can be checked.\n8. If there isn't enough material to answer a question at all, say so plainly under\n   that question rather than guessing.\n9. Where two source documents disagree (e.g. an early draft citing 86 survey responses\n   versus the finalised 191), use the figure the knowledge base marks as authoritative.\n10. Across the whole set of answers (not per question), check that six things are\n    covered somewhere: what the project is, who benefits, why it's needed, where,\n    how it will work, and when. If one of these has no home in any answer, flag it\n    once at the end, don't force it into an answer where it doesn't belong.\n11. Use the same figure for the same thing in every answer in this application (the\n    knowledge base's figure wins over anything else). If a figure is a projection\n    rather than something already true, say so every time it's used (\"by Year 3,\n    projected to reach...\").\n12. Never claim RSDG is the first, only, largest, or best at anything unless the\n    knowledge base says so in those exact words.\n13. Apply the tone specified in the bid details below (Friendly, Professional,\n    Formal, or Academic). Formal and Professional mean measured and evidence-led,\n    no contractions; Friendly allows contractions but keeps the same evidence\n    standard; Academic allows slightly longer sentences and fuller citation of the\n    underlying studies. The no-hype and never-invent rules apply regardless of tone.\n14. At the end of each answer, on its own line, state the count: \"Count: N words\"\n    or \"Count: N characters\", matching whichever unit the limit was given in (or\n    words, if no limit was given).\n15. After the drafted answers, always add a section headed exactly:\n    RECOMMENDATIONS TO STRENGTHEN THIS APPLICATION\n    Give 4-5 specific, bid-relevant suggestions for real evidence, material, or detail\n    RSDG could go and gather that isn't in the knowledge base or this bid's supplied\n    material, and that would make this particular application stronger given this\n    funder and this question set. Examples of the kind of thing this means: a specific\n    quote or testimonial from a named type of person, a letter of support from a named\n    partner not yet mentioned, a photo or visual that would help, a data point worth\n    confirming, a comparison worth adding. Tailor these to what this funder seems to\n    care about, not a generic list reused every time. These are suggestions for future\n    action, never facts presented as if already true; do not phrase a recommendation so\n    it reads as a claim about RSDG. This section is mandatory on every response, even\n    if the draft above already feels strong.\n16. After the recommendations, always add a final section headed exactly:\n    SOURCES USED\n    One line per distinct source used anywhere in the answers (e.g. \"Community\n    survey, 191 responses, autumn 2025\", \"RSDG Business Plan 2026-2031, financial\n    projections\", \"£58,000 reserve, Business Plan v5\"), in the order first used, no\n    duplicates. If a source was used in more than one answer, list it once.\n\nUK SECTOR BEST PRACTICE — apply these patterns, adapted to RSDG's actual stage:\n- Outputs vs outcomes. An output is what RSDG does (e.g. \"600 unique users in Year 1\").\n  An outcome is the change that results (e.g. \"more Rothes residents meeting weekly\n  physical activity guidelines\"). When a question asks about impact or outcomes,\n  answer with the outcome, evidenced by the output and survey data, not just a\n  restated output.\n- RSDG has not opened yet. It has no achieved track record of running the facility.\n  Never write an outcome claim as if it's already been measured (no \"our 65%\n  achievement rate\"). Every Year 1-3 figure in the knowledge base (600 users, 35%\n  occupancy, the financial projections) is a modelled TARGET from the business plan,\n  not a result. Say so plainly: \"projected\", \"targeting\", \"the business plan models\".\n  What RSDG can evidence now, and should lead with where relevant, is demand and\n  readiness: the 191-response survey, stakeholder and school engagement, the £33,000\n  whisky auction track record, the board's skills and experience.\n- Be specific, not vague, about activities: who, how many, how often, how long,\n  where. Prefer \"2 padel courts and 2 pickleball courts, bookable online, £15-20/hour\"\n  over \"modern sports facilities for the community.\"\n- Connect every claim to the funder's own stated priorities explicitly, naming the\n  priority and showing the match in the same sentence. Don't leave the assessor to\n  infer the connection. Never claim a match the FIT CHECK found doesn't exist.\n- Budget lines should be specific and traceable to the knowledge base's own cost\n  tables. Don't introduce a vague \"miscellaneous\" or unexplained contingency line;\n  where the business plan already includes a contingency (e.g. the 10% construction\n  contingency), it's legitimate because the plan explains what it covers, so explain\n  it the same way here if a budget question is asked.\n- Don't present the same pot of money as covering two different costs without saying\n  so; the knowledge base already flags where funders appear in more than one funding\n  table (e.g. Foundation Scotland, Robertson Trust appearing in both the Project 0 and\n  Year 1 operating tables) as a normal multi-year funder relationship, not double-\n  counting. Keep that same honesty if a budget or funding-mix question touches it.\n- Mirror the funder's own language and criteria wherever their guidelines or question\n  wording is available (from an uploaded document or the form), rather than reusing\n  RSDG's internal terminology by default.\n- Never mention another funder, another programme, or another project in this\n  application, that's the clearest sign of recycled, unedited text.\n- Before finalising, self-check against common rejection causes: has the actual\n  question been answered (not a nearby one); is anything vague that could be\n  specific; does any figure need the \"target, not achieved\" caveat from above; would\n  a reader unfamiliar with RSDG follow this without jargon.\n\nHOUSE WRITING STANDARDS — apply throughout, not just at the end:\n- Plain British English (organisation, programme, fundraising).\n- Evidence over assertion: every claim traces to a fact in the knowledge base or this\n  bid's supplied material. \"Raised over £33,000 through a community whisky auction\" is\n  usable; \"a highly successful fundraising operation\" is not, unless a figure backs it.\n- No em-dashes. Use commas, full stops, or brackets instead.\n- Human, not corporate: warm, clear, local, the way you'd talk to a neighbour about\n  something you're proud of. Professional but not stiff, friendly but not trivial.\n  This is a formal funding application, not marketing copy, so evidence and substance\n  lead; RSDG's own energetic brand voice comes through in what's actually true, not in\n  slogans or exclamation marks.\n- Active voice. Direct verbs. No throat-clearing (\"It's important to note that...\").\n  No unnamed-authority claims (\"studies show...\"). No rule-of-three padding unless\n  there genuinely are three things. No dramatic colons building to a punchline. Vary\n  sentence and paragraph length rather than settling into a uniform rhythm. No\n  summary paragraph tacked on at the end restating what was just said.\n- Never use these words/phrases: delve, moreover, furthermore, utilize, leverage\n  (verb), facilitate, robust, seamless, comprehensive, cutting-edge, holistic,\n  synergy, innovative, transformative, empower, myriad, plethora, foster, cultivate,\n  pivotal, embark, actionable, streamline, elevate, harness, unlock, journey,\n  compelling, impactful, crucial, ensure/ensuring, world-leading, unparalleled,\n  best-in-class, bold, vision, exciting, passionate, vibrant, remarkable, unique\n  (unless it's literally true and evidenced), state of the art, world class,\n  transform (as a verb for the project), \"we're delighted to\", \"don't hesitate to\n  get in touch\". No sentence should end in an exclamation mark, ever, in any tone.\n- Every acronym spelled out on first use in each answer, even ones the funder will\n  likely know: SCIO, MUGA, CAT, and any others that appear.\n- Don't patronise the reader. Write peer-to-peer. Assume the funder is intelligent and\n  reading many applications; be specific and get to the point.`;\n\nconst REVIEWER_SYSTEM_PROMPT = `You are reviewing a draft grant-application answer before RSDG sees it, after\nsomeone else has already drafted it. You have the same RSDG knowledge base the\nwriter had, plus this specific bid's supplied material, and the draft itself\n(including its plans, answers, and the recommendations section).\n\n${RSDG_KNOWLEDGE_BASE}\n\nDo not rewrite the answers. Report faults so they can be shown alongside the draft.\nCheck each of the following against the draft you're given, and report PASS or FAIL\nwith a one-line reason and, for a FAIL, the exact text at fault.\n\n1. Question answered. Does each answer's first sentence respond directly to the\n   question as worded? If a question has more than one part, is each part answered?\n2. Limit. If a word or character limit was given, is each answer within it (FAIL if\n   over, or more than 10% under)?\n3. Unsupported facts. List every number, date, sum of money, count of people, named\n   study, named partner, and named grant in the draft. For each, confirm it appears\n   in the RSDG knowledge base above or was supplied for this bid. FAIL and list any\n   you cannot verify this way. Put this check first if there's a FAIL, it's the most\n   serious kind.\n4. Placeholders. Does every [NEEDS INPUT: ...] the plan implied stay in the draft,\n   rather than being silently filled in or dropped? FAIL and name any that were\n   silently resolved.\n5. Funder name and priorities. Is the funder named consistently throughout? Is at\n   least one of the funder's stated priorities named and matched explicitly,\n   wherever the material given makes that possible?\n6. Wrong funder or project. Does the draft mention any funder, programme, or project\n   that isn't this one? This is the clearest sign of reused, unedited text.\n7. Consistency across answers. Compare every figure used more than once (membership\n   targets, costs, dates, percentages). FAIL on any mismatch and show both values.\n8. Acronyms. Is every acronym (SCIO, MUGA, CAT, others) spelled out on first use in\n   each answer that uses it?\n9. Hype and filler. Flag every instance of hype language (bold, vision, exciting,\n   passionate, vibrant, journey, remarkable, innovative, unique, state of the art,\n   world class, transformative, and similar), any exclamation mark, and any sentence\n   that makes no factual claim.\n10. Superlatives. Flag \"first\", \"only\", \"largest\", \"best\" unless the knowledge base\n    uses the exact same words.\n11. Plain English. Flag sentences over about 35 words, and any jargon a funder\n    reading many applications wouldn't immediately recognise.\n12. Projections stated as fact. Is every future or modelled figure (the Year 1-3\n    targets, the financial projections) clearly marked as a projection rather than\n    an achieved result?\n13. Money format. Pounds sign, full figures written out, no \"£36k\" style shorthand.\n14. Tone match. Does each answer actually match the tone setting given (Formal and\n    Professional: no contractions; Friendly: contractions fine; Academic: fuller\n    citation)? FAIL on contractions in Formal, or on stiff, distant phrasing in\n    Friendly.\n15. Repetition. Does any fact, figure, or phrase appear in more than one answer in\n    this application where the question didn't require repeating it? FAIL and name\n    the fact and the two answers it appears in.\n\nReturn exactly this structure:\n\nREVIEW\n1. Question answered: PASS/FAIL. reason\n2. Limit: PASS/FAIL. reason\n3. Unsupported facts: PASS/FAIL. reason\n4. Placeholders: PASS/FAIL. reason\n5. Funder name and priorities: PASS/FAIL. reason\n6. Wrong funder or project: PASS/FAIL. reason\n7. Consistency across answers: PASS/FAIL. reason\n8. Acronyms: PASS/FAIL. reason\n9. Hype and filler: PASS/FAIL. reason\n10. Superlatives: PASS/FAIL. reason\n11. Plain English: PASS/FAIL. reason\n12. Projections stated as fact: PASS/FAIL. reason\n13. Money format: PASS/FAIL. reason\n14. Tone match: PASS/FAIL. reason\n15. Repetition: PASS/FAIL. reason\n\nFLAGS FOR RSDG\n- one line each, plainest possible language, telling them what to check or fix\n- if every check passed, say so plainly instead of inventing something to flag`;\n\nconst PIPELINE_EXTRACT_SYSTEM_PROMPT = `You are extracting structured funder records from whatever raw material RSDG\nhas pasted or uploaded (a spreadsheet dumped as text, an email, notes, a\nfunder database export, anything). Turn it into a clean list for RSDG's\nfunding pipeline tracker.\n\nReturn ONLY valid JSON, no other text before or after it, in exactly this\nshape:\n\n{\"funders\": [\n  {\"name\": \"...\", \"appliesTo\": \"...\", \"amount\": \"...\", \"deadline\": \"...\", \"notes\": \"...\", \"url\": \"...\"}\n]}\n\nRules:\n- One object per distinct funding opportunity. If the source lists the same\n  funder for multiple distinct programmes or asks, create a separate entry\n  for each, using the same \"name\" for the funder each time.\n- \"name\": the funder or grant-making organisation's own name, as it appears\n  in the source.\n- \"appliesTo\": the specific grant, programme, or fund name if one is given\n  (not RSDG's own project), otherwise a short description of what it's for.\n  Leave \"\" if genuinely nothing is given.\n- \"amount\": a plain figure like \"£25,000\" or a range like \"£10,000-£100,000\".\n  If the source says a figure is unknown or not stated, use \"TBC\". Never\n  invent a figure.\n- \"deadline\": a plain description like \"31 October 2026\", \"Rolling\", or\n  \"Ongoing\", or \"\" if not stated. Never invent one.\n- \"notes\": 1-3 sentences, plain and factual: key eligibility criteria,\n  funding range, application process quirks, or caveats worth knowing before\n  applying. Condense, never copy a long block verbatim. Never invent detail\n  not present in the source.\n- \"url\": the single most useful link for applying or finding out more, if\n  one is given, otherwise \"\".\n- Never invent a fact, figure, or link that isn't in the source material.\n- If the source material contains nothing resembling funder or grant\n  information at all, return {\"funders\": []}.\n- Do not wrap the JSON in a code fence or add commentary. Return the raw\n  JSON object and nothing else.`;\n\nconst initial = {\n  funder: '',\n  project: '',\n  amount: '',\n  amountFor: '',\n  priorFunding: '',\n  priorFundingDetail: '',\n  wordLimit: '',\n  wordLimitType: 'words',\n  tone: 'Professional',\n  keyStory: '',\n  questions: '',\n};\n\nconst TONE_OPTIONS = ['Friendly', 'Professional', 'Formal', 'Academic'];\n\nconst READY_CHECKLIST_ITEMS = [\n  \"Read the funder's question again, then the first sentence of each answer. Does it answer that question, not a nearby one?\",\n  'Every number: do you know where it came from, and is it the same number used elsewhere in this application?',\n  \"Every claim about a partner: is that relationship real today, and would the partner agree with how it's described?\",\n  'Every study or report cited: do you have a copy on file, in case the funder asks?',\n  \"Is the funder's name right, with nothing left over from another application?\",\n  'Is anything a projection or a hope rather than a fact? If so, is it described that way?',\n  \"Have you removed or explained every acronym a stranger wouldn't know?\",\n  \"Is there anything you'd be embarrassed to read aloud to the assessor?\",\n  'If this answer touches the budget, is it real quotes rather than guesses, with the arithmetic checked?',\n  \"Has someone who wasn't involved in writing it read it?\",\n  'Did you come back to it after a break, rather than marking it ready straight after drafting?',\n  'Is it within the limit, in the right format, with every document the funder asked for ready to attach?',\n];\n\nfunction readFileAsBase64(file) {\n  return new Promise((resolve, reject) => {\n    const reader = new FileReader();\n    reader.onload = () => resolve(reader.result.split(',')[1]);\n    reader.onerror = reject;\n    reader.readAsDataURL(file);\n  });\n}\n\nasync function fileToContentBlock(file) {\n  const type = file.type;\n  if (type === 'application/pdf') {\n    const data = await readFileAsBase64(file);\n    return { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data } };\n  }\n  if (type.startsWith('image/')) {\n    const data = await readFileAsBase64(file);\n    return { type: 'image', source: { type: 'base64', media_type: type, data } };\n  }\n  if (\n    type === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' ||\n    file.name.toLowerCase().endsWith('.docx')\n  ) {\n    // mammoth is loaded globally via a <script> tag in index.html\n    const arrayBuffer = await file.arrayBuffer();\n    const { value } = await mammoth.extractRawText({ arrayBuffer });\n    return { type: 'text', text: `[Uploaded file: ${file.name}]\\n${value}` };\n  }\n  // plain text / fallback\n  const text = await file.text();\n  return { type: 'text', text: `[Uploaded file: ${file.name}]\\n${text}` };\n}\n\nfunction FileDrop({ label, files, setFiles, multiple }) {\n  const inputRef = useRef(null);\n  const onChange = (e) => {\n    const picked = Array.from(e.target.files || []);\n    setFiles(multiple ? [...files, ...picked] : picked.slice(0, 1));\n    e.target.value = '';\n  };\n  return (\n    <div>\n      <button\n        type=\"button\"\n        onClick={() => inputRef.current?.click()}\n        style={{\n          display: 'flex',\n          alignItems: 'center',\n          gap: 8,\n          border: `1.5px dashed ${COLORS.blue}55`,\n          background: '#f7fafc',\n          borderRadius: 4,\n          padding: '10px 14px',\n          color: COLORS.blue,\n          fontWeight: 600,\n          fontSize: 14,\n          cursor: 'pointer',\n          width: '100%',\n          textAlign: 'left',\n        }}\n      >\n        <Upload size={16} />\n        {label}\n      </button>\n      <input\n        ref={inputRef}\n        type=\"file\"\n        multiple={multiple}\n        onChange={onChange}\n        style={{ display: 'none' }}\n        accept=\".pdf,.docx,.doc,.png,.jpg,.jpeg,.txt\"\n      />\n      {files.length > 0 && (\n        <div style={{ marginTop: 8, display: 'flex', flexDirection: 'column', gap: 4 }}>\n          {files.map((f, i) => (\n            <div\n              key={i}\n              style={{\n                display: 'flex',\n                alignItems: 'center',\n                justifyContent: 'space-between',\n                fontSize: 13,\n                color: COLORS.ink,\n                background: '#fff',\n                border: '1px solid #e2e8ee',\n                borderRadius: 4,\n                padding: '5px 10px',\n              }}\n            >\n              <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{f.name}</span>\n              <button\n                type=\"button\"\n                onClick={() => setFiles(files.filter((_, idx) => idx !== i))}\n                style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#94a3b8', display: 'flex' }}\n              >\n                <X size={14} />\n              </button>\n            </div>\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n\nfunction Field({ label, hint, children }) {\n  return (\n    <div style={{ marginBottom: 20 }}>\n      <label style={{ display: 'block', fontWeight: 700, color: COLORS.blue, fontSize: 14, marginBottom: 4 }}>\n        {label}\n      </label>\n      {hint && <div style={{ fontSize: 12.5, color: '#5b7183', marginBottom: 6, fontWeight: 300 }}>{hint}</div>}\n      {children}\n    </div>\n  );\n}\n\nconst inputStyle = {\n  width: '100%',\n  border: '1.5px solid #d7e1e8',\n  borderRadius: 4,\n  padding: '9px 12px',\n  fontSize: 14.5,\n  fontFamily: 'inherit',\n  color: COLORS.ink,\n  boxSizing: 'border-box',\n  background: '#fff',\n};\n\nasync function callClaude(content, systemPrompt) {\n  const response = await fetch('/api/draft', {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify({\n      model: 'claude-sonnet-5',\n      max_tokens: 20000,\n      system: systemPrompt || SYSTEM_PROMPT,\n      messages: [{ role: 'user', content }],\n    }),\n  });\n\n  if (!response.ok) {\n    // A failure here comes back as a normal, small JSON body (streaming\n    // only starts once Anthropic has actually accepted the request), so\n    // it's safe to read this one in full rather than as a stream.\n    const raw = await response.text();\n    let data;\n    try {\n      data = JSON.parse(raw);\n    } catch (e) {\n      throw new Error(\n        `Server returned something that wasn't JSON (HTTP ${response.status}). Actual response, first 400 characters: ${\n          raw ? raw.slice(0, 400) : '(completely empty response body)'\n        }`\n      );\n    }\n    const detail =\n      (data && data.error && (data.error.message || JSON.stringify(data.error))) ||\n      (data && data.detail) ||\n      JSON.stringify(data).slice(0, 400);\n    const keyDiag = data && data._keyDiagnostic ? ` [key check: ${data._keyDiagnostic}]` : '';\n    throw new Error(`API error (HTTP ${response.status}): ${detail}${keyDiag}`);\n  }\n\n  // Success: read this as a stream of server-sent events and assemble the\n  // text ourselves, rather than waiting for one single response. A long\n  // generation would otherwise risk timing out the connection before it's\n  // done, this way data keeps flowing the whole time.\n  //\n  // Guard against a different failure: if the connection stalls silently\n  // partway through (nothing more ever arrives, but the stream never\n  // properly closes either), reading would hang forever and the UI would\n  // never leave \"loading\". Give each individual read a time limit, so a\n  // stall always surfaces as a clear error instead of an infinite spinner.\n  const reader = response.body.getReader();\n  const decoder = new TextDecoder();\n  let buffer = '';\n  let fullText = '';\n  let sawText = false;\n  let sawThinking = false;\n  let streamError = null;\n  const IDLE_TIMEOUT_MS = 60000;\n\n  async function readWithTimeout() {\n    let timer;\n    const timeout = new Promise((_, reject) => {\n      timer = setTimeout(() => reject(new Error('IDLE_TIMEOUT')), IDLE_TIMEOUT_MS);\n    });\n    try {\n      return await Promise.race([reader.read(), timeout]);\n    } finally {\n      clearTimeout(timer);\n    }\n  }\n\n  while (true) {\n    let result;\n    try {\n      result = await readWithTimeout();\n    } catch (e) {\n      try {\n        reader.cancel();\n      } catch (e2) {}\n      throw new Error(\n        `The connection went quiet for over a minute and was stopped rather than left hanging. Try again${\n          sawText ? ' (a partial draft may have been generated, but not shown, since it stopped mid-way)' : ''\n        }.`\n      );\n    }\n    const { done, value } = result;\n    if (done) break;\n    buffer += decoder.decode(value, { stream: true });\n    const lines = buffer.split('\\n');\n    buffer = lines.pop(); // the last entry may be a partial line, keep it for next time\n    for (const line of lines) {\n      const trimmed = line.trim();\n      if (!trimmed.startsWith('data:')) continue;\n      const jsonStr = trimmed.slice(5).trim();\n      if (!jsonStr) continue;\n      let evt;\n      try {\n        evt = JSON.parse(jsonStr);\n      } catch (e) {\n        continue;\n      }\n      if (evt.type === 'content_block_delta' && evt.delta && evt.delta.type === 'text_delta') {\n        fullText += evt.delta.text;\n        sawText = true;\n      } else if (evt.type === 'content_block_start' && evt.content_block && evt.content_block.type === 'thinking') {\n        sawThinking = true;\n      } else if (evt.type === 'error') {\n        streamError = evt.error ? evt.error.message || JSON.stringify(evt.error) : JSON.stringify(evt);\n      }\n    }\n  }\n\n  if (streamError) {\n    throw new Error(`API error during streaming: ${streamError}`);\n  }\n  if (!sawText) {\n    throw new Error(\n      sawThinking\n        ? 'Claude used up the response budget on reasoning and never produced an actual answer. Try again, or if it keeps happening this needs a higher token budget.'\n        : 'The stream ended with no text content.'\n    );\n  }\n  return fullText;\n}\n\nfunction BidBuilder() {\n  const [form, setForm] = useState(initial);\n  const [guidelineFiles, setGuidelineFiles] = useState([]);\n  const [supportFiles, setSupportFiles] = useState([]);\n  const [status, setStatus] = useState('idle'); // idle | loading | done | error\n  const [answers, setAnswers] = useState('');\n  const [errorMsg, setErrorMsg] = useState('');\n  const [copied, setCopied] = useState(false);\n  const [everDone, setEverDone] = useState(false);\n  const [draftNumber, setDraftNumber] = useState(1);\n  const [extraRounds, setExtraRounds] = useState([]); // [{ note, files }]\n  const [addingInfo, setAddingInfo] = useState(false);\n  const [newNote, setNewNote] = useState('');\n  const [newFiles, setNewFiles] = useState([]);\n  const [regenStatus, setRegenStatus] = useState('idle'); // idle | loading | error\n  const [reviewStatus, setReviewStatus] = useState('idle'); // idle | loading | done | error\n  const [reviewText, setReviewText] = useState('');\n  const [reviewErrorDetail, setReviewErrorDetail] = useState('');\n  const [readyChecks, setReadyChecks] = useState({});\n\n  const set = (key) => (e) => setForm({ ...form, [key]: e.target.value });\n\n  const canSubmit = form.funder.trim() && form.project.trim() && form.questions.trim();\n\n  async function getOriginalContentBlocks() {\n    const textSummary = `\nBID DETAILS SUPPLIED BY RSDG\n-----------------------------\nFunder / programme: ${form.funder}\nSpecific project this funding is for: ${form.project}\nAmount requested: ${form.amount || '(not given)'}\nWhat the money specifically pays for: ${form.amountFor || '(not given)'}\nPrevious funding from this funder: ${form.priorFunding || '(not given)'}${\n      form.priorFundingDetail ? ` — ${form.priorFundingDetail}` : ''\n    }\nWord/character limit per answer: ${form.wordLimit ? `${form.wordLimit} ${form.wordLimitType}` : '(none given — use judgement, keep answers concise)'}\nTone for this application: ${form.tone}\nStory or fact to feature prominently, if any: ${form.keyStory || '(none given)'}\n`.trim();\n\n    const fileBlocks = [];\n    for (const f of guidelineFiles) {\n      fileBlocks.push({ type: 'text', text: `[This is the funder's own guidelines document: ${f.name}]` });\n      fileBlocks.push(await fileToContentBlock(f));\n    }\n    for (const f of supportFiles) {\n      fileBlocks.push({ type: 'text', text: `[This is RSDG supporting material: ${f.name}]` });\n      fileBlocks.push(await fileToContentBlock(f));\n    }\n    return [{ type: 'text', text: textSummary }, ...fileBlocks];\n  }\n\n  function questionsBlock() {\n    return { type: 'text', text: `FUNDER'S APPLICATION QUESTIONS (answer each in turn, in this order):\\n${form.questions}` };\n  }\n\n  async function runReview(baseBlocks, draftText) {\n    setReviewStatus('loading');\n    setReviewErrorDetail('');\n    try {\n      const reviewContent = [...baseBlocks, { type: 'text', text: `DRAFT TO REVIEW:\\n${draftText}` }];\n      const review = await callClaude(reviewContent, REVIEWER_SYSTEM_PROMPT);\n      setReviewText(review);\n      setReviewStatus('done');\n    } catch (err) {\n      console.error(err);\n      setReviewErrorDetail(err && err.message ? err.message : String(err));\n      setReviewStatus('error');\n    }\n  }\n\n  async function handleSubmit() {\n    setStatus('loading');\n    setErrorMsg('');\n    try {\n      const baseBlocks = await getOriginalContentBlocks();\n      const content = [...baseBlocks, questionsBlock()];\n      const draft = await callClaude(content);\n      setAnswers(draft);\n      setStatus('done');\n      setEverDone(true);\n      runReview(content, draft);\n    } catch (err) {\n      console.error(err);\n      setErrorMsg(err && err.message ? err.message : 'Something went wrong generating the draft. Please try again.');\n      setStatus('error');\n    }\n  }\n\n  async function handleRegenerate() {\n    const thisRound = { note: newNote, files: newFiles };\n    const updatedRounds = [...extraRounds, thisRound];\n    setRegenStatus('loading');\n    setErrorMsg('');\n    try {\n      const baseBlocks = await getOriginalContentBlocks();\n      const roundBlocks = [];\n      for (let i = 0; i < updatedRounds.length; i++) {\n        const r = updatedRounds[i];\n        roundBlocks.push({\n          type: 'text',\n          text: `ADDITIONAL INFORMATION SUPPLIED AFTER DRAFT ${i + 1}:\\n${r.note || '(no notes, see attached files)'}`,\n        });\n        for (const f of r.files) {\n          roundBlocks.push({ type: 'text', text: `[Uploaded with this round: ${f.name}]` });\n          roundBlocks.push(await fileToContentBlock(f));\n        }\n      }\n      const revisionInstruction = {\n        type: 'text',\n        text: `This is a revision. The ADDITIONAL INFORMATION above was supplied after seeing the previous draft below. Produce a complete, updated draft that incorporates it, following all ground rules, house standards, the [NEEDS INPUT] flagging, and the mandatory recommendations section. Write the full draft again, not just a list of changes.\\n\\nPREVIOUS DRAFT:\\n${answers}`,\n      };\n      const content = [...baseBlocks, ...roundBlocks, revisionInstruction, questionsBlock()];\n      const draft = await callClaude(content);\n      setAnswers(draft);\n      setExtraRounds(updatedRounds);\n      setNewNote('');\n      setNewFiles([]);\n      setAddingInfo(false);\n      setDraftNumber((n) => n + 1);\n      setRegenStatus('idle');\n      runReview(content, draft);\n    } catch (err) {\n      console.error(err);\n      setErrorMsg(err && err.message ? err.message : 'Something went wrong generating the updated draft. Please try again.');\n      setRegenStatus('error');\n    }\n  }\n\n  function handleCopy() {\n    navigator.clipboard.writeText(answers);\n    setCopied(true);\n    setTimeout(() => setCopied(false), 2000);\n  }\n\n  function handleDownload() {\n    const blob = new Blob([answers], { type: 'text/plain' });\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement('a');\n    a.href = url;\n    a.download = `RSDG-bid-draft-${form.funder.replace(/[^a-z0-9]+/gi, '-') || 'draft'}-v${draftNumber}.txt`;\n    a.click();\n    URL.revokeObjectURL(url);\n  }\n\n  function handleReset() {\n    setForm(initial);\n    setGuidelineFiles([]);\n    setSupportFiles([]);\n    setAnswers('');\n    setStatus('idle');\n    setEverDone(false);\n    setDraftNumber(1);\n    setExtraRounds([]);\n    setAddingInfo(false);\n    setNewNote('');\n    setNewFiles([]);\n    setRegenStatus('idle');\n    setReviewStatus('idle');\n    setReviewText('');\n    setReviewErrorDetail('');\n    setReadyChecks({});\n  }\n\n  return (\n    <div style={{ maxWidth: 900, margin: '0 auto', padding: '0 24px 60px' }}>\n        {!everDone && (\n          <div\n            style={{\n              background: '#fff',\n              marginTop: -24,\n              borderRadius: 6,\n              boxShadow: '0 1px 3px rgba(0,60,90,0.12)',\n              padding: '28px 28px 8px',\n            }}\n          >\n            <SectionTitle n=\"1\" title=\"This bid\" />\n            <Field label=\"Which funder or programme is this for?\">\n              <input style={inputStyle} value={form.funder} onChange={set('funder')} placeholder=\"e.g. Sport Scotland — Community Sport Fund\" />\n            </Field>\n            <Field label=\"Do you have the funder's guidelines?\" hint=\"Optional, but it helps the draft match what they're actually looking for.\">\n              <FileDrop label=\"Upload funder guidelines\" files={guidelineFiles} setFiles={setGuidelineFiles} multiple={false} />\n            </Field>\n            <Field label=\"Which specific project or piece of work is the funding for?\">\n              <textarea style={{ ...inputStyle, minHeight: 60, resize: 'vertical' }} value={form.project} onChange={set('project')} placeholder=\"e.g. Refurbishing the outdoor multi-use games area\" />\n            </Field>\n            <Field label=\"How much are you asking for, and what does it pay for?\">\n              <div style={{ display: 'flex', gap: 10 }}>\n                <input style={{ ...inputStyle, maxWidth: 140 }} value={form.amount} onChange={set('amount')} placeholder=\"£ amount\" />\n                <input style={inputStyle} value={form.amountFor} onChange={set('amountFor')} placeholder=\"what it specifically pays for\" />\n              </div>\n            </Field>\n            <Field label=\"Have you had funding from this funder before?\">\n              <div style={{ display: 'flex', gap: 16, marginBottom: 8 }}>\n                {['Yes', 'No'].map((opt) => (\n                  <label key={opt} style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 14 }}>\n                    <input\n                      type=\"radio\"\n                      name=\"prior\"\n                      checked={form.priorFunding === opt}\n                      onChange={() => setForm({ ...form, priorFunding: opt })}\n                    />\n                    {opt}\n                  </label>\n                ))}\n              </div>\n              <input style={inputStyle} value={form.priorFundingDetail} onChange={set('priorFundingDetail')} placeholder=\"Any detail worth adding (optional)\" />\n            </Field>\n            <Field label=\"Word or character limit per answer, if the funder sets one\">\n              <div style={{ display: 'flex', gap: 14, alignItems: 'center', flexWrap: 'wrap' }}>\n                <input\n                  style={{ ...inputStyle, maxWidth: 110 }}\n                  value={form.wordLimit}\n                  onChange={set('wordLimit')}\n                  placeholder=\"e.g. 250\"\n                  inputMode=\"numeric\"\n                />\n                <div style={{ display: 'flex', gap: 16 }}>\n                  {['words', 'characters'].map((opt) => (\n                    <label key={opt} style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 14 }}>\n                      <input\n                        type=\"radio\"\n                        name=\"wordLimitType\"\n                        checked={form.wordLimitType === opt}\n                        onChange={() => setForm({ ...form, wordLimitType: opt })}\n                      />\n                      {opt === 'words' ? 'Words' : 'Characters'}\n                    </label>\n                  ))}\n                </div>\n              </div>\n            </Field>\n            <Field label=\"Tone for this application\" hint=\"Formal and Professional read as measured and evidence-led. Friendly allows contractions. Academic allows fuller citation of the studies. Every tone still follows the no-hype, never-invent rules.\">\n              <select\n                value={form.tone}\n                onChange={(e) => setForm({ ...form, tone: e.target.value })}\n                style={{ ...inputStyle, maxWidth: 220 }}\n              >\n                {TONE_OPTIONS.map((t) => (\n                  <option key={t} value={t}>\n                    {t}\n                  </option>\n                ))}\n              </select>\n            </Field>\n\n            <SectionTitle n=\"2\" title=\"What makes this application strong\" />\n            <Field label=\"A particular result, story, or fact you want front and centre\">\n              <textarea style={{ ...inputStyle, minHeight: 70, resize: 'vertical' }} value={form.keyStory} onChange={set('keyStory')} placeholder=\"e.g. Since the padel courts opened, junior membership has grown from...\" />\n            </Field>\n            <Field label=\"Anything else specific to this bid\" hint=\"Only needed for things not already in the business plan, e.g. a new quote, a recent letter of support, updated figures. The core project, board and financial detail is already built in.\">\n              <FileDrop label=\"Upload additional documents\" files={supportFiles} setFiles={setSupportFiles} multiple={true} />\n            </Field>\n\n            <SectionTitle n=\"3\" title=\"The funder's questions\" />\n            <Field label=\"Paste the application questions exactly as the funder gives them\">\n              <textarea\n                style={{ ...inputStyle, minHeight: 140, resize: 'vertical' }}\n                value={form.questions}\n                onChange={set('questions')}\n                placeholder={'1. Describe your organisation and its beneficiaries.\\n2. What difference will this funding make?\\n...'}\n              />\n            </Field>\n\n            <div style={{ padding: '10px 0 26px' }}>\n              <button\n                onClick={handleSubmit}\n                disabled={!canSubmit || status === 'loading'}\n                style={{\n                  background: canSubmit ? COLORS.orange : '#cbd5df',\n                  color: '#fff',\n                  border: 'none',\n                  borderRadius: 5,\n                  padding: '13px 26px',\n                  fontSize: 15.5,\n                  fontWeight: 700,\n                  cursor: canSubmit ? 'pointer' : 'not-allowed',\n                  display: 'flex',\n                  alignItems: 'center',\n                  gap: 8,\n                  width: '100%',\n                  justifyContent: 'center',\n                }}\n              >\n                {status === 'loading' ? (\n                  <>\n                    <Loader2 size={18} className=\"spin\" style={{ animation: 'spin 1s linear infinite' }} />\n                    Drafting your application…\n                  </>\n                ) : (\n                  <>\n                    Draft this application\n                    <ChevronRight size={18} />\n                  </>\n                )}\n              </button>\n              <p style={{ fontSize: 12.5, color: '#5b7183', textAlign: 'center', marginTop: 10, fontWeight: 300 }}>\n                Answers are drafted only from RSDG's business plan and what's entered above. Anything we can't back up is flagged, not invented.\n              </p>\n              {status === 'error' && (\n                <div style={{ display: 'flex', gap: 8, alignItems: 'flex-start', color: '#b42318', fontSize: 13.5, marginTop: 10 }}>\n                  <AlertCircle size={16} style={{ flexShrink: 0, marginTop: 1 }} />\n                  {errorMsg}\n                </div>\n              )}\n            </div>\n          </div>\n        )}\n\n        {everDone && (\n          <div\n            style={{\n              background: '#fff',\n              marginTop: -24,\n              borderRadius: 6,\n              boxShadow: '0 1px 3px rgba(0,60,90,0.12)',\n              padding: '28px',\n            }}\n          >\n            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 18, flexWrap: 'wrap', gap: 10 }}>\n              <h2 style={{ color: COLORS.blue, fontSize: 20, fontWeight: 800, margin: 0 }}>\n                Draft answers <span style={{ color: '#8fa3b3', fontWeight: 600, fontSize: 14 }}>· draft {draftNumber}</span>\n              </h2>\n              <div style={{ display: 'flex', gap: 8 }}>\n                <button onClick={handleCopy} style={ghostBtn}>\n                  {copied ? <Check size={15} /> : <Copy size={15} />}\n                  {copied ? 'Copied' : 'Copy all'}\n                </button>\n                <button onClick={handleDownload} style={ghostBtn}>\n                  <Download size={15} />\n                  Download\n                </button>\n              </div>\n            </div>\n            <div\n              style={{\n                whiteSpace: 'pre-wrap',\n                fontSize: 14.5,\n                lineHeight: 1.65,\n                color: COLORS.ink,\n                borderTop: `3px solid ${COLORS.yellow}`,\n                paddingTop: 18,\n                opacity: regenStatus === 'loading' ? 0.5 : 1,\n              }}\n              dangerouslySetInnerHTML={{ __html: highlightFlags(answers) }}\n            />\n\n            {regenStatus === 'loading' && (\n              <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 18, color: COLORS.blue, fontSize: 14, fontWeight: 600 }}>\n                <Loader2 size={16} style={{ animation: 'spin 1s linear infinite' }} />\n                Updating your draft…\n              </div>\n            )}\n            {regenStatus === 'error' && (\n              <div style={{ display: 'flex', gap: 8, alignItems: 'flex-start', color: '#b42318', fontSize: 13.5, marginTop: 14 }}>\n                <AlertCircle size={16} style={{ flexShrink: 0, marginTop: 1 }} />\n                {errorMsg}\n              </div>\n            )}\n\n            {reviewStatus === 'loading' && (\n              <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 22, color: COLORS.blue, fontSize: 14, fontWeight: 600 }}>\n                <Loader2 size={16} style={{ animation: 'spin 1s linear infinite' }} />\n                Running the review pass…\n              </div>\n            )}\n            {reviewStatus === 'error' && (\n              <div style={{ display: 'flex', gap: 8, alignItems: 'flex-start', color: '#b42318', fontSize: 13.5, marginTop: 18 }}>\n                <AlertCircle size={16} style={{ flexShrink: 0, marginTop: 1 }} />\n                Review pass failed: {reviewErrorDetail}\n              </div>\n            )}\n            {reviewStatus === 'done' && (\n              <div style={{ marginTop: 24, padding: '18px 20px', background: '#eef6fb', borderLeft: `4px solid ${COLORS.blue}`, borderRadius: 4 }}>\n                <div style={{ color: COLORS.blueDark, fontWeight: 800, fontSize: 14.5, marginBottom: 10 }}>Review pass</div>\n                <div\n                  style={{ whiteSpace: 'pre-wrap', fontSize: 13.5, lineHeight: 1.6, color: COLORS.ink }}\n                  dangerouslySetInnerHTML={{ __html: highlightReview(reviewText) }}\n                />\n              </div>\n            )}\n\n            {(reviewStatus === 'done' || reviewStatus === 'error') && (\n              <div style={{ marginTop: 20, padding: 18, background: '#f7fafc', borderRadius: 6, border: '1px solid #e2e8ee' }}>\n                <div style={{ fontWeight: 800, color: COLORS.blue, fontSize: 14, marginBottom: 10 }}>Before you mark this ready</div>\n                {READY_CHECKLIST_ITEMS.map((item, i) => (\n                  <label key={i} style={{ display: 'flex', alignItems: 'flex-start', gap: 8, fontSize: 13.5, marginBottom: 8, cursor: 'pointer' }}>\n                    <input\n                      type=\"checkbox\"\n                      checked={!!readyChecks[i]}\n                      onChange={() => setReadyChecks((prev) => ({ ...prev, [i]: !prev[i] }))}\n                      style={{ marginTop: 3 }}\n                    />\n                    <span>{item}</span>\n                  </label>\n                ))}\n                <div style={{ fontSize: 12.5, color: '#5b7183', marginTop: 6 }}>\n                  {Object.values(readyChecks).filter(Boolean).length} of {READY_CHECKLIST_ITEMS.length} checked\n                </div>\n              </div>\n            )}\n\n            {addingInfo && regenStatus !== 'loading' && (\n              <div style={{ marginTop: 24, padding: 18, background: '#f7fafc', borderRadius: 6, border: '1px solid #e2e8ee' }}>\n                <Field label=\"What would you like to add or change?\" hint=\"A missing figure, a quote, an answer to one of the recommendations above, a correction, anything.\">\n                  <textarea\n                    style={{ ...inputStyle, minHeight: 90, resize: 'vertical' }}\n                    value={newNote}\n                    onChange={(e) => setNewNote(e.target.value)}\n                    placeholder=\"e.g. Here's a quote from a Rothes Primary PE teacher: ...\"\n                  />\n                </Field>\n                <Field label=\"Attach a document, if useful\" hint=\"Optional.\">\n                  <FileDrop label=\"Upload document\" files={newFiles} setFiles={setNewFiles} multiple={true} />\n                </Field>\n                <div style={{ display: 'flex', gap: 10, marginTop: 4 }}>\n                  <button\n                    onClick={handleRegenerate}\n                    disabled={!newNote.trim() && newFiles.length === 0}\n                    style={{\n                      background: newNote.trim() || newFiles.length > 0 ? COLORS.orange : '#cbd5df',\n                      color: '#fff',\n                      border: 'none',\n                      borderRadius: 5,\n                      padding: '10px 20px',\n                      fontSize: 14,\n                      fontWeight: 700,\n                      cursor: newNote.trim() || newFiles.length > 0 ? 'pointer' : 'not-allowed',\n                    }}\n                  >\n                    Generate updated draft\n                  </button>\n                  <button\n                    onClick={() => {\n                      setAddingInfo(false);\n                      setNewNote('');\n                      setNewFiles([]);\n                    }}\n                    style={{ background: 'none', border: 'none', color: '#5b7183', fontSize: 14, fontWeight: 600, cursor: 'pointer' }}\n                  >\n                    Cancel\n                  </button>\n                </div>\n              </div>\n            )}\n\n            <div style={{ display: 'flex', gap: 12, marginTop: 26, flexWrap: 'wrap' }}>\n              {!addingInfo && (\n                <button\n                  onClick={() => setAddingInfo(true)}\n                  disabled={regenStatus === 'loading'}\n                  style={{\n                    background: COLORS.blue,\n                    color: '#fff',\n                    border: 'none',\n                    borderRadius: 5,\n                    padding: '10px 20px',\n                    fontSize: 14,\n                    fontWeight: 700,\n                    cursor: regenStatus === 'loading' ? 'not-allowed' : 'pointer',\n                  }}\n                >\n                  Add more information to this bid\n                </button>\n              )}\n              <button\n                onClick={handleReset}\n                disabled={regenStatus === 'loading'}\n                style={{\n                  background: 'none',\n                  border: `1.5px solid ${COLORS.blue}`,\n                  color: COLORS.blue,\n                  borderRadius: 5,\n                  padding: '10px 20px',\n                  fontSize: 14,\n                  fontWeight: 700,\n                  cursor: regenStatus === 'loading' ? 'not-allowed' : 'pointer',\n                }}\n              >\n                Start a new application\n              </button>\n            </div>\n          </div>\n        )}\n        <style>{`\n          @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }\n          ::placeholder { color: #a3b3bf; font-weight: 300; }\n        `}</style>\n      </div>\n  );\n}\n\nfunction SectionTitle({ n, title }) {\n  return (\n    <div style={{ display: 'flex', alignItems: 'center', gap: 10, margin: '4px 0 18px' }}>\n      <div\n        style={{\n          width: 24,\n          height: 24,\n          borderRadius: '50%',\n          background: COLORS.blue,\n          color: '#fff',\n          fontSize: 12.5,\n          fontWeight: 800,\n          display: 'flex',\n          alignItems: 'center',\n          justifyContent: 'center',\n          flexShrink: 0,\n        }}\n      >\n        {n}\n      </div>\n      <h2 style={{ fontSize: 17, fontWeight: 800, color: COLORS.ink, margin: 0 }}>{title}</h2>\n    </div>\n  );\n}\n\nconst ghostBtn = {\n  display: 'flex',\n  alignItems: 'center',\n  gap: 6,\n  background: '#fff',\n  border: '1.5px solid #d7e1e8',\n  color: COLORS.blue,\n  borderRadius: 5,\n  padding: '7px 13px',\n  fontSize: 13,\n  fontWeight: 700,\n  cursor: 'pointer',\n};\n\nfunction highlightFlags(text) {\n  const escaped = text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n  let withFlags = escaped.replace(\n    /\\[[^\\]]*\\]/g,\n    (match) =>\n      `<span style=\"background:#fff3cd; color:#7a5b00; padding:1px 5px; border-radius:3px; font-weight:600;\">${match}</span>`\n  );\n  withFlags = withFlags.replace(\n    /^(Plan:)/gm,\n    `<span style=\"color:#5b7183; font-weight:700; font-style:italic;\">$1</span>`\n  );\n  withFlags = withFlags.replace(\n    /^(Answer:)/gm,\n    `<span style=\"color:${COLORS.blue}; font-weight:700;\">$1</span>`\n  );\n  withFlags = withFlags.replace(\n    /^FIT CHECK$/gm,\n    `<span style=\"display:inline-block; margin-top:4px; color:${COLORS.blueDark}; font-weight:800; font-size:14.5px; letter-spacing:0.2px;\">Fit check</span>`\n  );\n  withFlags = withFlags.replace(\n    /^(Count: .+)$/gm,\n    `<span style=\"color:#94a3b8; font-size:12.5px; font-weight:600;\">$1</span>`\n  );\n  withFlags = withFlags.replace(\n    /RECOMMENDATIONS TO STRENGTHEN THIS APPLICATION/g,\n    `</div><div style=\"margin-top:28px; padding:18px 20px; background:#f0f9f0; border-left:4px solid ${COLORS.green}; border-radius:4px;\"><div style=\"color:${COLORS.blueDark}; font-weight:800; font-size:14.5px; letter-spacing:0.2px; margin-bottom:10px;\">Recommendations to strengthen this application</div>`\n  );\n  return withFlags.replace(\n    /SOURCES USED/g,\n    `</div><div style=\"margin-top:20px; padding:18px 20px; background:#f7fafc; border-left:4px solid ${COLORS.blue}; border-radius:4px;\"><div style=\"color:${COLORS.blueDark}; font-weight:800; font-size:14.5px; letter-spacing:0.2px; margin-bottom:10px;\">Sources used</div>`\n  );\n}\n\nfunction highlightReview(text) {\n  const escaped = text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n  return escaped\n    .replace(/\\bFAIL\\b/g, '<span style=\"color:#b42318; font-weight:800;\">FAIL</span>')\n    .replace(/\\bPASS\\b/g, '<span style=\"color:#20ab21; font-weight:700;\">PASS</span>')\n    .replace(\n      /^(FLAGS FOR RSDG)/m,\n      `<span style=\"display:inline-block; margin-top:14px; color:${COLORS.blueDark}; font-weight:800; font-size:13.5px;\">$1</span>`\n    );\n}\n\n/* ---------------- Funding pipeline tracker ---------------- */\n\nconst STATUS_OPTIONS = ['Not started', 'Researching', 'Drafting', 'Submitted', 'Awarded', 'Declined', 'Ongoing', 'Secured'];\n\nconst STATUS_COLORS = {\n  'Not started': '#94a3b8',\n  Researching: '#0284c7',\n  Drafting: COLORS.orange,\n  Submitted: '#a855f7',\n  Awarded: COLORS.green,\n  Declined: '#dc2626',\n  Ongoing: '#0891b2',\n  Secured: COLORS.green,\n};\n\nconst fieldLabelStyle = { fontSize: 11.5, fontWeight: 700, color: COLORS.blue, marginBottom: 3 };\n\nfunction statusPillStyle(color) {\n  return {\n    display: 'inline-flex',\n    alignItems: 'center',\n    justifyContent: 'center',\n    width: 108,\n    height: 24,\n    lineHeight: '16px',\n    boxSizing: 'border-box',\n    fontSize: 11.5,\n    fontWeight: 700,\n    fontFamily: 'inherit',\n    color: '#fff',\n    background: color || '#94a3b8',\n    border: 'none',\n    outline: 'none',\n    borderRadius: 20,\n    padding: '0 6px',\n    margin: 0,\n    whiteSpace: 'nowrap',\n    overflow: 'hidden',\n    textOverflow: 'ellipsis',\n    textAlign: 'center',\n    WebkitAppearance: 'none',\n    MozAppearance: 'none',\n    appearance: 'none',\n  };\n}\n\nfunction StatusPicker({ value, onChange }) {\n  const [open, setOpen] = useState(false);\n  return (\n    <div style={{ position: 'relative', display: 'inline-block' }}>\n      <button type=\"button\" onClick={() => setOpen((o) => !o)} style={{ ...statusPillStyle(STATUS_COLORS[value]), cursor: 'pointer' }}>\n        {value}\n      </button>\n      {open && (\n        <>\n          <div style={{ position: 'fixed', inset: 0, zIndex: 30 }} onClick={() => setOpen(false)} />\n          <div\n            style={{\n              position: 'absolute',\n              top: '130%',\n              left: 0,\n              background: '#fff',\n              border: '1px solid #e2e8ee',\n              borderRadius: 6,\n              boxShadow: '0 4px 14px rgba(0,60,90,0.16)',\n              zIndex: 40,\n              minWidth: 150,\n              overflow: 'hidden',\n            }}\n          >\n            {STATUS_OPTIONS.map((s) => (\n              <div\n                key={s}\n                onClick={() => {\n                  onChange(s);\n                  setOpen(false);\n                }}\n                style={{\n                  padding: '8px 12px',\n                  fontSize: 13,\n                  cursor: 'pointer',\n                  color: COLORS.ink,\n                  background: s === value ? '#f0f4f7' : '#fff',\n                  display: 'flex',\n                  alignItems: 'center',\n                  gap: 8,\n                }}\n              >\n                <span style={{ width: 8, height: 8, borderRadius: '50%', background: STATUS_COLORS[s] || '#94a3b8', flexShrink: 0 }} />\n                {s}\n              </div>\n            ))}\n          </div>\n        </>\n      )}\n    </div>\n  );\n}\n\nfunction seedFunders() {\n  const rows = [\n    // Capital portfolio (Project 1 build, target ~£1.55M)\n    ['Scottish Land Fund', 'Land purchase', '£35,000', 'Not started', 'Application planned mid-2026', ''],\n    ['Rothes Wind Farm', 'Project 1 (capital)', '£170,000', 'Researching', 'Approximate; to be discussed. Part of £200k+ overall relationship with RSDG.', ''],\n    ['SportScotland', 'Sub-projects 1b/1c', '£100,000', 'Not started', '', ''],\n    [\n      'SSEN Community Benefit Funding',\n      'Project 1, Regional Fund',\n      '£500,000',\n      'Not started',\n      'Fund ID S52883. Range is £40,000–£500,000 depending on scale of ask. Closed as of the last GrantFinder update (18/07/2025), stated to reopen in 2026, worth checking current status before assuming it is closed.',\n      'https://www.ssen-transmission.co.uk/information-centre/community-benefit-fund/regional-community-benefit-fund/',\n    ],\n    ['Garfield Weston Foundation', 'Sub-project 1d (pavilion)', '£30,000', 'Not started', '', ''],\n    ['Peter Harrison Foundation', 'Sub-project 1b (courts)', '£30,000', 'Not started', '', ''],\n    ['Forsyth Foundation', 'Project 1 (capital tranche)', '£30,000', 'Researching', 'Relationship established', ''],\n    ['Scottish Landfill Communities', 'Sub-project 1a (groundworks)', '£25,000', 'Not started', '', ''],\n    ['Weir Charitable Trust', 'Sub-project 1b or 1d', '£25,000', 'Not started', '', ''],\n    ['Local fundraising', 'Capital, general', '£25,000', 'Ongoing', '', ''],\n    ['Barclays Community Sport', 'Sub-project 1b (courts)', '£20,000', 'Not started', '', ''],\n    ['CARES (Net Zero)', 'Energy/sustainability elements', '£20,000', 'Not started', '', ''],\n    ['HIE', 'Project 0/1, general relationship', 'TBC', 'Researching', 'In discussion', ''],\n    [\n      'HIE',\n      'Community Right to Buy Fund: registering community interest in land',\n      '£5,000',\n      'Not started',\n      'Covers up to 80% of costs. Worth checking with the CAT solicitor whether Right to Buy registration is a relevant route alongside the Community Asset Transfer, since they are related but distinct legal mechanisms.',\n      'https://www.hie.co.uk/support/browse-all-support-services/support-for-community-organisations/community-right-to-buy-fund/',\n    ],\n    [\n      'LTA Quick Access Loan Scheme',\n      'Loan contingency if grant funding falls short',\n      '£250,000',\n      'Not started',\n      'Interest-free loan, not a grant. Held in reserve as a fallback; the income model does not assume any loan servicing cost.',\n      '',\n    ],\n    [\n      'Moray Council',\n      'Place Based Investment Programme or similar',\n      'TBC',\n      'Not started',\n      \"Named in the fundraising strategy as a potential statutory contribution, not yet explored.\",\n      '',\n    ],\n    [\n      'UK Shared Prosperity Fund',\n      'Successor programmes, to be monitored',\n      'TBC',\n      'Not started',\n      'No specific current programme identified; the fundraising strategy flags this as something to watch as new UK government funding rounds emerge.',\n      '',\n    ],\n    ['Glen Grant', 'Corporate sponsorship prospect (distillery community investment)', 'TBC', 'Not started', 'Named in the business plan as a local distillery to approach via community investment or CSR team.', ''],\n    ['Macallan', 'Corporate sponsorship prospect (distillery community investment)', 'TBC', 'Not started', 'Named in the business plan as a local distillery to approach via community investment or CSR team.', ''],\n    ['Cardhu', 'Corporate sponsorship prospect (distillery community investment)', 'TBC', 'Not started', 'Named in the business plan as a local distillery to approach via community investment or CSR team.', ''],\n    ['Craigellachie', 'Corporate sponsorship prospect (distillery community investment)', 'TBC', 'Not started', 'Named in the business plan as a local distillery to approach via community investment or CSR team.', ''],\n    ['Aberlour', 'Corporate sponsorship prospect (distillery community investment)', 'TBC', 'Not started', 'Named in the business plan as a local distillery to approach via community investment or CSR team.', ''],\n    // Project 0 operating (~£152k-176k)\n    ['Rothes Wind Farm', 'Project 0 Y1 and Y2 (operating)', '£40,000', 'Researching', 'To be discussed', ''],\n    ['Robertson Trust', 'Project 0 Y1', '£25,000', 'Not started', '', ''],\n    ['Foundation Scotland', 'Project 0 Y1', '£15,000', 'Not started', '', 'https://www.foundationscotland.org.uk/apply-for-funding/funding-available'],\n    ['Forsyth Foundation', 'Project 0 Y1 and Y2 (operating)', '£10,000', 'Researching', 'Committed in principle', ''],\n    ['William Grant Foundation', 'Project 0 Y1', '£6,000', 'Not started', '', ''],\n    ['ScottishPower Foundation', 'Project 0 Y2', '£5,000', 'Not started', '', ''],\n    ['Local fundraising', 'Project 0 Y1 and Y2, community events', '£15,000', 'Ongoing', '', ''],\n    ['Additional pipeline (DO-secured)', 'Project 0 Y2 buffer', '£5,000', 'Not started', '', ''],\n    [\n      'Foundation Scotland',\n      'Dorenell Wind Farm Community Benefit Fund',\n      '£30,000',\n      'Not started',\n      'Fund ID S46290, deadline 30/11/2026. Larger awards considered on request. Benefits Dufftown, Auchindoun, Glenrinnes, Glenlivet, Inveravon and Cabrach specifically, not Rothes itself, so check carefully whether a genuinely qualifying beneficiary link can be shown before applying.',\n      'https://www.foundationscotland.org.uk/dorenell',\n    ],\n    // Year 1 operating raise (during Project 1, target £140,000)\n    ['Foundation Scotland', 'Y1 operating', '£25,000', 'Not started', 'Follow-on after P0 grant', ''],\n    ['Robertson Trust', 'Y1 operating', '£25,000', 'Not started', 'Follow-on after P0 grant', ''],\n    ['William Grant Foundation', 'Y1 operating', '£15,000', 'Not started', 'Follow-on after P0 grant', ''],\n    ['Local fundraising', 'Y1 operating, community campaign', '£15,000', 'Ongoing', 'Major launch-year campaign', ''],\n    ['Forsyth Foundation', 'Y1 operating', '£10,000', 'Researching', 'Continuing relationship', ''],\n    ['ScottishPower Foundation', 'Y1 operating', '£10,000', 'Not started', 'Follow-on after P0 grant', ''],\n    ['Additional pipeline (DO-secured)', 'Y1 operating, during P1', '£40,000', 'Not started', '', ''],\n    // Already in hand\n    ['Existing reserves', 'Project 0 opening balance', '£58,000', 'Secured', \"RSDG's cash position at the start of Project 0\", ''],\n    ['Whisky for Rothes auction', 'Community fundraising track record', '£33,000', 'Secured', 'Actual figure was over £33,000. Run via Just Whisky.', ''],\n    // Added from GrantFinder research (Sept 2026), not yet reflected in the business plan\n    [\n      'David and June Gordon Memorial Trust',\n      'Music, arts, youth activity or ecumenical services in NE Scotland',\n      '£2,000',\n      'Not started',\n      'Fund ID S48430. Typical grants £500–£2,000; £15,000–£20,000 distributed annually in total. Rolling; trustees meet April and October, apply 3-4 weeks ahead. Excludes individuals. Small amount, best suited to a specific programme element (e.g. youth coaching or an arts/music strand) rather than the core build.',\n      'https://www.davidandjunegordonmemorialtrust.co.uk/',\n    ],\n    [\n      'Gordon and Ena Baxter Foundation',\n      'Capital expenditure, sport priority (N Scotland)',\n      '£25,000',\n      'Not started',\n      \"Fund ID S47290. Grants typically £100–£25,000. Requires match funding already secured, roughly 50%+ of project cost. Excludes core/running costs and land/building purchase, so fits a specific capital element rather than the whole build. Two-stage application, four rounds a year.\",\n      'http://www.gebfoundation.com/',\n    ],\n    [\n      'Hays Travel Foundation',\n      'Youth (up to 25) sport, education or health project',\n      '£15,000',\n      'Not started',\n      'Fund ID S44428. Typically £2,000–£15,000; average award last year was around £3,500. Depends on Hays Travel having a branch near Rothes or Elgin, worth checking the branch locator before applying.',\n      'https://info.haystravel.co.uk/foundation',\n    ],\n    [\n      'HITRANS',\n      'Community Cycle Parking Grant',\n      'TBC',\n      'Not started',\n      'Fund ID S55188. Discretionary, no set maximum. Closed to applications as of the last GrantFinder update, and only relevant if a cycle-parking element is added to the site plan. Narrow fit against the current project scope.',\n      'https://hitrans.org.uk/travel/funding-for-active-travel-infrastructure-projects-in-the-community-and-workplace/',\n    ],\n    [\n      'Misses Barrie Charitable Trust',\n      'General charitable purposes incl. amateur sport (Scotland)',\n      '£3,000',\n      'Not started',\n      'Fund ID S32651. Typically £1,000–£3,000, occasional larger grant. No website; apply by post/email. High volume of unsolicited applications, unsuccessful applicants are not notified.',\n      '',\n    ],\n    [\n      'Moray Local Action Fund',\n      'Community-led project, revenue or capital (Moray)',\n      '£25,000',\n      'Not started',\n      'Fund ID S52555. Two tiers: small grants to £5,000, main grants £5,000–£25,000. This round closed 20/07/2026; projects had to complete by 31/03/2027. Watch TSI Moray for the next round.',\n      'https://www.moraylag.org.uk/funding-copy',\n    ],\n    [\n      'Moray Coastal Communities Fund',\n      'Coastal or marine-linked community project',\n      '£50,000',\n      'Not started',\n      'Medium grants £10,000–£20,000; strategic grants £20,001–£50,000. Deadline 18/09/2026, 5pm, confirmed live. Requires the project to sit within 12 nautical miles of the Moray coastline with a clear coast/sea link. Rothes is inland, so this looks like a poor geographic fit rather than a live opportunity, flagging rather than recommending.',\n      'https://www.moray.gov.uk/benefits-and-grants/council-and-government-grants/moray-coastal-communities-fund-grant-scheme/',\n    ],\n    [\n      'Moray Communities Mental Health and Wellbeing Fund',\n      'Adult mental health and wellbeing initiatives (Moray)',\n      '£15,000',\n      'Not started',\n      'Fund ID S47611. Small grants up to £2,000 (1 year only); individual org grants up to £10,000/year (up to 2 years); partnership grants up to £15,000/year (up to 2 years). Closed to applications as of the last GrantFinder update; watch TSI Moray for the next round. Priorities (rural isolation, older people, at-risk groups) line up well with the walking football and older-adult wellbeing programming.',\n      'https://tsimoray.org.uk/funding/moray-communities-mental-health-and-wellbeing/',\n    ],\n    // From Localgiving's recommended grants export (18 of a stated 52), September 2026.\n    // Eligibility reasoning in that export is AI-generated and hasn't been independently\n    // verified, treat as a lead worth checking, not a confirmed fit. Two entries from\n    // that list are skipped here as likely duplicates of funders already above: Weir\n    // Charitable Trust (identical funder, same ~£25,000 figure) and one of two near-\n    // identical Garfield Weston Foundation \"regular grants\" listings, merged into one.\n    [\n      'Sir Jules Thorn Charitable Trust',\n      'Ann Rylands Small Donations',\n      '£5,000',\n      'Not started',\n      \"Rolling programme, up to £5,000, for UK-registered charities improving health or care services for people with ill health or disability. One application per charity per 12 months.\",\n      'https://julesthorntrust.org.uk/programmes/ann-rylands-small-donations',\n    ],\n    [\n      'One Stop Carriers for Causes',\n      'Carriers for Causes Grant',\n      '£1,000',\n      'Not started',\n      'Up to £1,000 for not-for-profits, schools, and community/sports groups improving local places. Small amount, likely best suited to a specific item (e.g. equipment) rather than the core build.',\n      'https://www.aandslandscape.co.uk/grant/one-stop-carriers-for-causes/',\n    ],\n    [\n      'Forte Charitable Foundation',\n      'Forte Charitable Foundation Grants',\n      '£100,000',\n      'Not started',\n      'Small Grants £2,000-£10,000 (community support) or Major Grants £10,000-£100,000 (family support), up to 50% of costs. Requires operating in the most deprived 15% (urban) or 50% (rural) areas by the Index of Multiple Deprivation, worth checking Rothes/AB38\\u2019s ranking before applying. Not open to CICs or local authorities.',\n      'https://www.fortecharitablefoundation.org.uk/',\n    ],\n    [\n      'Garfield Weston Foundation',\n      'Regular and Major Grants (general programme)',\n      'TBC',\n      'Not started',\n      'Regular grants £1,000-£100,000 for running costs, a specific activity, or capital, no fixed deadlines. Major grants (£100,000+) generally need £1M+ turnover or project cost, and roughly half of project/capital funding already secured before applying. This is in addition to the pavilion-specific ask above; Localgiving\\u2019s export listed this same open programme twice, merged into one entry here.',\n      'https://garfieldweston.org/for-grant-applicants/how-to-apply/',\n    ],\n    [\n      \"Global's Make Some Noise\",\n      'Make Some Noise Grant 2026',\n      '£70,000',\n      'Not started',\n      'For small UK charities delivering frontline, in-depth support. Requires annual income between £30,000 and £1 million, RSDG\\u2019s income fits. Two-stage process, submit an Expression of Interest first. Funding opens April 2026.',\n      'https://makesomenoise.com/charity',\n    ],\n    [\n      'John Good Group / Matthew Good Foundation',\n      'Grants for Good',\n      '£5,000',\n      'Not started',\n      'Unrestricted grants of £2,000-£5,000 for small charities/community groups with income under £50,000, RSDG qualifies. Quarterly rounds. The online application can\\u2019t be saved partway through, plan to complete it in one sitting.',\n      'https://forms.monday.com/forms/bb78e04bc3edc5e011bc9419ad89cd9f?r=use1',\n    ],\n    [\n      'The Hedley Foundation',\n      'Grants for Young People',\n      '£5,000',\n      'Not started',\n      'Average award around £5,000, for small/medium charities benefiting young people, disabled people, older people, or other disadvantaged groups. Apply at least 6 weeks before a review meeting.',\n      'http://www.hedleyfoundation.org.uk/apply-now',\n    ],\n    [\n      'Jessie Spencer Trust',\n      'Jessie Spencer Trust Grants',\n      'TBC',\n      'Not started',\n      'For registered charities and CICs with sustained public benefit projects. Requires the most recent audited accounts. No stated income cap.',\n      'https://jessiespencer.grantapps.net/form1/',\n    ],\n    [\n      'Greene King',\n      'Proud To Pitch In Community Fund',\n      '£3,000',\n      'Not started',\n      'Cash grants up to £3,000 for grassroots and community sports clubs. Apply via nomination or directly through the ActionFunder platform.',\n      'https://app.actionfunder.org/funder-profile/1033',\n    ],\n    [\n      'Biffa Award',\n      'Recreation theme',\n      '£75,000',\n      'Not started',\n      'Grants of £10,000-£75,000; total project cost must stay under £200,000. Site must be within 5 miles of a Biffa Operation or 10 miles of a Biffa/licensed landfill site, worth checking before applying. Needs a Third Party Contributor covering at least 10% of the ask, planning permission already granted, and a minimum of 104 public-access days a year.',\n      'https://www.biffa-award.org/recreation',\n    ],\n    [\n      \"Robert Barr's Charitable Trust\",\n      \"Robert Barr's Charitable Trust Grant\",\n      'TBC',\n      'Not started',\n      'Scotland-only, favours capital projects over running costs; supports recreational facilities among other causes. Apply in writing via Shepherd and Wedderburn LLP, Glasgow, no online form.',\n      'https://funding.scot/funds/a0Rb0000000Ng4nEAC/robert-barrs-charitable-trust',\n    ],\n    [\n      'Robin Greaves Foundation',\n      'Robin Greaves Foundation Grant',\n      'TBC',\n      'Not started',\n      'Supports amateur sport, community sport and health participation, and PE or leadership training for young people. Apply by emailing the Foundation directly, no formal application form.',\n      'https://www.aandslandscape.co.uk/grant/robin-greaves-foundations/',\n    ],\n    [\n      \"The Clothworkers' Foundation\",\n      'Open Grants Programme',\n      '£25,000',\n      'Not started',\n      'Capital only (buildings, fixtures, equipment, vehicles). At least 50% of service users must fall within the Foundation\\u2019s specific priority groups (including older people and people with disabilities), worth checking this threshold carefully against RSDG\\u2019s broader user base.',\n      'https://www.clothworkersfoundation.org.uk/what-we-fund/#open',\n    ],\n    [\n      'The Truemark Trust',\n      'General grants',\n      'TBC',\n      'Not started',\n      'Prefers small, local, innovative charities and less-popular beneficiary groups. Funds both capital and revenue costs. Apply in writing, no online form (PO Box 2, Liss, Hampshire).',\n      '',\n    ],\n    [\n      'Warburtons',\n      'Community Grants',\n      '£400',\n      'Not started',\n      'Small grants up to £400 only, for health, skills, or community-place improvements, reviewed quarterly. Modest relative to RSDG\\u2019s capital needs, best suited to a very specific small item.',\n      'https://www.warburtons.co.uk/our-company/sustainability/within-the-community/giving-donating/financial-giving/',\n    ],\n    [\n      'easyfundraising',\n      'Impact Fund',\n      '£1,000',\n      'Not started',\n      '20 grants of £1,000 each, unrestricted use (equipment, running costs, events, and similar). This round opens 24 September 2026.',\n      'https://www.easyfundraising.org.uk/impact-fund',\n      '8 November 2026, midnight',\n    ],\n  ];\n  return rows.map(([name, appliesTo, amount, status, notes, url, deadline], i) => ({\n    id: `f${i}`,\n    name,\n    appliesTo,\n    amount,\n    deadline: deadline || '',\n    status,\n    notes,\n    url,\n  }));\n}\n\nfunction parseAmount(amountStr) {\n  // Pulls the highest number out of a figure like \"£35,000\" or \"£40,000-£500,000\".\n  // TBC / discretionary / non-numeric values correctly return 0.\n  const matches = String(amountStr).replace(/,/g, '').match(/[\\d.]+/g);\n  if (!matches) return 0;\n  return Math.max(...matches.map(parseFloat));\n}\n\nfunction groupFunders(list) {\n  // Preserves first-seen order of each funder name\n  const order = [];\n  const map = {};\n  list.forEach((f) => {\n    if (!map[f.name]) {\n      map[f.name] = [];\n      order.push(f.name);\n    }\n    map[f.name].push(f);\n  });\n  return order.map((name) => ({ name, rows: map[name] }));\n}\n\nfunction FunderLine({ f, indent, expandedId, setExpandedId, updateRow, deleteRow }) {\n  const isOpen = expandedId === f.id;\n  return (\n    <React.Fragment>\n      <tr style={{ borderBottom: isOpen ? 'none' : '1px solid #eef2f5' }}>\n        <td style={{ padding: '8px 10px', fontWeight: 600, color: COLORS.ink, paddingLeft: indent ? 28 : 10, wordBreak: 'break-word' }}>\n          {indent && <span style={{ color: '#c2ccd4', marginRight: 6 }}>—</span>}\n          {indent ? f.appliesTo || f.name : f.name}\n        </td>\n        <td style={{ padding: '8px 10px', color: COLORS.ink, wordBreak: 'break-word' }}>{f.amount}</td>\n        <td style={{ padding: '8px 10px', color: '#5b7183', wordBreak: 'break-word' }}>{f.deadline || '—'}</td>\n        <td style={{ padding: '8px 10px' }}>\n          <StatusPicker value={f.status} onChange={(s) => updateRow(f.id, { status: s })} />\n        </td>\n        <td style={{ padding: '8px 10px', textAlign: 'center' }}>\n          {f.url ? (\n            <a href={f.url} target=\"_blank\" rel=\"noopener noreferrer\" title={f.url} style={{ color: COLORS.blue, display: 'inline-flex' }}>\n              <ExternalLink size={15} />\n            </a>\n          ) : (\n            <span style={{ color: '#d7e1e8' }}>—</span>\n          )}\n        </td>\n        <td style={{ padding: '8px 10px' }}>\n          <button\n            onClick={() => setExpandedId(isOpen ? null : f.id)}\n            title={isOpen ? 'Close details' : 'Edit details'}\n            style={{\n              border: 'none',\n              background: 'none',\n              color: COLORS.blue,\n              cursor: 'pointer',\n              display: 'flex',\n              alignItems: 'center',\n              transform: isOpen ? 'rotate(90deg)' : 'rotate(0deg)',\n              transition: 'transform 0.15s ease',\n            }}\n          >\n            <ChevronRight size={18} />\n          </button>\n        </td>\n      </tr>\n      {isOpen && (\n        <tr style={{ borderBottom: '1px solid #eef2f5' }}>\n          <td colSpan={6} style={{ padding: '4px 10px 18px', background: '#f7fafc' }}>\n            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10, padding: '12px 4px 4px' }}>\n              <div>\n                <div style={fieldLabelStyle}>Funder name</div>\n                <input style={inputStyle} value={f.name} onChange={(e) => updateRow(f.id, { name: e.target.value })} />\n              </div>\n              <div>\n                <div style={fieldLabelStyle}>Amount</div>\n                <input style={inputStyle} value={f.amount} onChange={(e) => updateRow(f.id, { amount: e.target.value })} />\n              </div>\n              <div>\n                <div style={fieldLabelStyle}>Applies to</div>\n                <input style={inputStyle} value={f.appliesTo} onChange={(e) => updateRow(f.id, { appliesTo: e.target.value })} />\n              </div>\n              <div>\n                <div style={fieldLabelStyle}>Deadline (if there is one)</div>\n                <input\n                  style={inputStyle}\n                  value={f.deadline}\n                  onChange={(e) => updateRow(f.id, { deadline: e.target.value })}\n                  placeholder=\"e.g. 31 March 2027, or 'rolling'\"\n                />\n              </div>\n              <div style={{ gridColumn: '1 / -1' }}>\n                <div style={fieldLabelStyle}>URL (link to further information)</div>\n                <input\n                  style={inputStyle}\n                  value={f.url}\n                  onChange={(e) => updateRow(f.id, { url: e.target.value })}\n                  placeholder=\"https://…\"\n                />\n              </div>\n              <div style={{ gridColumn: '1 / -1' }}>\n                <div style={fieldLabelStyle}>Notes</div>\n                <textarea\n                  style={{ ...inputStyle, minHeight: 60, resize: 'vertical' }}\n                  value={f.notes}\n                  onChange={(e) => updateRow(f.id, { notes: e.target.value })}\n                />\n              </div>\n            </div>\n            {indent && (\n              <p style={{ fontSize: 11.5, color: '#94a3b8', margin: '8px 4px 0' }}>\n                Renaming \"Funder name\" here moves this ask out of its group if the new name doesn't match the others.\n              </p>\n            )}\n            <button\n              onClick={() => {\n                deleteRow(f.id);\n                setExpandedId(null);\n              }}\n              style={{\n                marginTop: 6,\n                background: 'none',\n                border: 'none',\n                color: '#b42318',\n                fontSize: 12.5,\n                fontWeight: 700,\n                cursor: 'pointer',\n              }}\n            >\n              Remove this funder from the pipeline\n            </button>\n          </td>\n        </tr>\n      )}\n    </React.Fragment>\n  );\n}\n\nfunction fundKey(r) {\n  return `${r.name}|||${r.appliesTo}`;\n}\n\nfunction mergeWithSeed(stored, deletedKeys) {\n  const seed = seedFunders();\n  const seedByKey = {};\n  seed.forEach((r) => {\n    seedByKey[fundKey(r)] = r;\n  });\n  const storedKeys = new Set(stored.map(fundKey));\n  const deletedSet = new Set(deletedKeys || []);\n\n  // Backfill fields (like the new url column) onto existing rows without touching\n  // anything the user has already edited (status, notes, or a url they've set).\n  const backfilled = stored.map((r) => {\n    const match = seedByKey[fundKey(r)];\n    const patch = {};\n    if (r.url === undefined) patch.url = (match && match.url) || '';\n    if (r.deadline === undefined) patch.deadline = (match && match.deadline) || '';\n    return Object.keys(patch).length ? { ...r, ...patch } : r;\n  });\n\n  // Add any funds from the current seed list that aren't in storage yet AND\n  // haven't been deliberately deleted before, with ids that can't collide\n  // with whatever's already there.\n  const usedIds = new Set(backfilled.map((r) => r.id));\n  let n = 0;\n  const additions = seed\n    .filter((r) => !storedKeys.has(fundKey(r)) && !deletedSet.has(fundKey(r)))\n    .map((r) => {\n      let id = r.id;\n      while (usedIds.has(id)) {\n        id = `fnew${n++}`;\n      }\n      usedIds.add(id);\n      return { ...r, id };\n    });\n\n  return [...backfilled, ...additions];\n}\n\nfunction SortableHeader({ label, sortKey, sortBy, sortDir, onSort }) {\n  const isActive = sortBy === sortKey;\n  return (\n    <th\n      onClick={() => onSort(sortKey)}\n      title={`Sort by ${label}`}\n      style={{\n        padding: '8px 10px',\n        color: COLORS.blue,\n        fontWeight: 800,\n        fontSize: 12,\n        cursor: 'pointer',\n        userSelect: 'none',\n        whiteSpace: 'nowrap',\n      }}\n    >\n      {label}{' '}\n      <span style={{ color: isActive ? COLORS.orange : '#c2ccd4', fontSize: 10 }}>\n        {isActive ? (sortDir === 'asc' ? '▲' : '▼') : '↕'}\n      </span>\n    </th>\n  );\n}\n\nfunction PipelineTracker() {\n  const [funders, setFunders] = useState(null); // null = still loading\n  const [loadError, setLoadError] = useState(false);\n  const [loadErrorDetail, setLoadErrorDetail] = useState('');\n  const [showAdd, setShowAdd] = useState(false);\n  const [newFunder, setNewFunder] = useState({ name: '', appliesTo: '', amount: '', deadline: '', status: 'Not started', notes: '', url: '' });\n  const [expandedId, setExpandedId] = useState(null);\n  const [expandedGroups, setExpandedGroups] = useState({});\n  const [deletedKeys, setDeletedKeys] = useState([]);\n  const [sortBy, setSortBy] = useState(null); // 'funder' | 'amount' | 'status' | null\n  const [sortDir, setSortDir] = useState('asc');\n  const [pdfStatus, setPdfStatus] = useState('idle'); // idle | working | error\n  const [pdfErrorDetail, setPdfErrorDetail] = useState('');\n  const [showBulkAdd, setShowBulkAdd] = useState(false);\n  const [bulkPasteText, setBulkPasteText] = useState('');\n  const [bulkFiles, setBulkFiles] = useState([]);\n  const [bulkStatus, setBulkStatus] = useState('idle'); // idle | extracting | preview | error\n  const [bulkErrorDetail, setBulkErrorDetail] = useState('');\n  const [bulkPreview, setBulkPreview] = useState([]); // [{ ...funder fields, include: true }]\n\n  function handleSort(key) {\n    if (sortBy === key) {\n      setSortDir((d) => (d === 'asc' ? 'desc' : 'asc'));\n    } else {\n      setSortBy(key);\n      setSortDir('asc');\n    }\n  }\n\n  function toggleGroup(name) {\n    setExpandedGroups((prev) => ({ ...prev, [name]: !prev[name] }));\n  }\n\n  async function pipelineGet() {\n    const res = await fetch('/api/pipeline');\n    if (!res.ok) {\n      const body = await res.text().catch(() => '');\n      throw new Error(`Pipeline load failed (HTTP ${res.status}): ${body.slice(0, 300) || 'no detail returned'}`);\n    }\n    const data = await res.json();\n    if (!data || !data.value) return null;\n    const parsed = JSON.parse(data.value);\n    // Older saves were a bare array with no record of deletions — treat that\n    // as \"nothing deleted yet\" rather than losing the data.\n    if (Array.isArray(parsed)) {\n      return { funders: parsed, deletedKeys: [] };\n    }\n    return { funders: parsed.funders || [], deletedKeys: parsed.deletedKeys || [] };\n  }\n\n  async function pipelineSet(fundersList, deletedKeysList) {\n    const res = await fetch('/api/pipeline', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ value: JSON.stringify({ funders: fundersList, deletedKeys: deletedKeysList }) }),\n    });\n    if (!res.ok) {\n      const body = await res.text().catch(() => '');\n      throw new Error(`Pipeline save failed (HTTP ${res.status}): ${body.slice(0, 300) || 'no detail returned'}`);\n    }\n  }\n\n  useEffect(() => {\n    (async () => {\n      try {\n        const loaded = await pipelineGet();\n        if (loaded && Array.isArray(loaded.funders) && loaded.funders.length > 0) {\n          const merged = mergeWithSeed(loaded.funders, loaded.deletedKeys);\n          setFunders(merged);\n          setDeletedKeys(loaded.deletedKeys || []);\n          if (merged.length !== loaded.funders.length || JSON.stringify(merged) !== JSON.stringify(loaded.funders)) {\n            await pipelineSet(merged, loaded.deletedKeys || []);\n          }\n        } else {\n          const seeded = seedFunders();\n          setFunders(seeded);\n          setDeletedKeys([]);\n          await pipelineSet(seeded, []);\n        }\n      } catch (err) {\n        // Key doesn't exist yet, or storage failed — seed locally and try to save\n        console.error(err);\n        const seeded = seedFunders();\n        setFunders(seeded);\n        setDeletedKeys([]);\n        try {\n          await pipelineSet(seeded, []);\n        } catch (e2) {\n          console.error(e2);\n          setLoadErrorDetail(e2 && e2.message ? e2.message : String(e2));\n          setLoadError(true);\n        }\n      }\n    })();\n  }, []);\n\n  async function persist(updatedFunders, updatedDeletedKeys) {\n    const dk = updatedDeletedKeys !== undefined ? updatedDeletedKeys : deletedKeys;\n    setFunders(updatedFunders);\n    if (updatedDeletedKeys !== undefined) setDeletedKeys(updatedDeletedKeys);\n    try {\n      await pipelineSet(updatedFunders, dk);\n    } catch (err) {\n      console.error(err);\n      setLoadErrorDetail(err && err.message ? err.message : String(err));\n      setLoadError(true);\n    }\n  }\n\n  function updateRow(id, patch) {\n    persist(funders.map((f) => (f.id === id ? { ...f, ...patch } : f)));\n  }\n\n  function deleteRow(id) {\n    const target = funders.find((f) => f.id === id);\n    const nextDeletedKeys = target ? [...deletedKeys, fundKey(target)] : deletedKeys;\n    persist(\n      funders.filter((f) => f.id !== id),\n      nextDeletedKeys\n    );\n  }\n\n  function addRow() {\n    if (!newFunder.name.trim()) return;\n    const row = { ...newFunder, id: `f${Date.now()}` };\n    persist([...funders, row]);\n    setNewFunder({ name: '', appliesTo: '', amount: '', deadline: '', status: 'Not started', notes: '', url: '' });\n    setShowAdd(false);\n  }\n\n  async function spreadsheetToText(file) {\n    const arrayBuffer = await file.arrayBuffer();\n    const workbook = XLSX.read(arrayBuffer, { type: 'array' });\n    const parts = [];\n    for (const sheetName of workbook.SheetNames) {\n      const sheet = workbook.Sheets[sheetName];\n      const csv = XLSX.utils.sheet_to_csv(sheet);\n      parts.push(`[Sheet: ${sheetName}]\\n${csv}`);\n    }\n    return parts.join('\\n\\n');\n  }\n\n  async function handleExtract() {\n    setBulkStatus('extracting');\n    setBulkErrorDetail('');\n    try {\n      const textParts = [];\n      if (bulkPasteText.trim()) {\n        textParts.push(`PASTED TEXT:\\n${bulkPasteText.trim()}`);\n      }\n      for (const f of bulkFiles) {\n        const isSpreadsheet = /\\.(xlsx|xls|csv)$/i.test(f.name);\n        if (isSpreadsheet) {\n          const csvText = await spreadsheetToText(f);\n          textParts.push(`UPLOADED SPREADSHEET (${f.name}):\\n${csvText}`);\n        } else {\n          const raw = await f.text();\n          textParts.push(`UPLOADED FILE (${f.name}):\\n${raw}`);\n        }\n      }\n      if (textParts.length === 0) {\n        throw new Error('Paste some text or upload a file first.');\n      }\n      const content = [{ type: 'text', text: textParts.join('\\n\\n---\\n\\n') }];\n      const raw = await callClaude(content, PIPELINE_EXTRACT_SYSTEM_PROMPT);\n      let parsed;\n      try {\n        parsed = JSON.parse(raw.trim());\n      } catch (e) {\n        // Claude occasionally wraps JSON in a code fence despite instructions; try stripping one.\n        const stripped = raw.trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();\n        parsed = JSON.parse(stripped);\n      }\n      const extracted = Array.isArray(parsed.funders) ? parsed.funders : [];\n      const existingNames = new Set(funders.map((f) => f.name.trim().toLowerCase()));\n      const withMeta = extracted.map((f, i) => ({\n        name: f.name || '',\n        appliesTo: f.appliesTo || '',\n        amount: f.amount || 'TBC',\n        deadline: f.deadline || '',\n        notes: f.notes || '',\n        url: f.url || '',\n        include: true,\n        possibleDuplicate: existingNames.has((f.name || '').trim().toLowerCase()),\n        _key: `preview${i}`,\n      }));\n      setBulkPreview(withMeta);\n      setBulkStatus('preview');\n    } catch (err) {\n      console.error(err);\n      setBulkErrorDetail(err && err.message ? err.message : String(err));\n      setBulkStatus('error');\n    }\n  }\n\n  function toggleBulkInclude(key) {\n    setBulkPreview((prev) => prev.map((r) => (r._key === key ? { ...r, include: !r.include } : r)));\n  }\n\n  function confirmBulkAdd() {\n    const toAdd = bulkPreview\n      .filter((r) => r.include)\n      .map((r, i) => ({\n        id: `fbulk${Date.now()}${i}`,\n        name: r.name,\n        appliesTo: r.appliesTo,\n        amount: r.amount,\n        deadline: r.deadline,\n        status: 'Not started',\n        notes: r.notes,\n        url: r.url,\n      }));\n    if (toAdd.length === 0) return;\n    persist([...funders, ...toAdd]);\n    setShowBulkAdd(false);\n    setBulkPasteText('');\n    setBulkFiles([]);\n    setBulkStatus('idle');\n    setBulkPreview([]);\n  }\n\n  function cancelBulkAdd() {\n    setShowBulkAdd(false);\n    setBulkPasteText('');\n    setBulkFiles([]);\n    setBulkStatus('idle');\n    setBulkErrorDetail('');\n    setBulkPreview([]);\n  }\n\n  function escapeHtml(str) {\n    return String(str)\n      .replace(/&/g, '&amp;')\n      .replace(/</g, '&lt;')\n      .replace(/>/g, '&gt;');\n  }\n\n  function handleDownloadPdf() {\n    setPdfStatus('idle');\n    try {\n      // Opened synchronously in direct response to the click, so pop-up blockers allow it.\n      const printWindow = window.open('', '_blank');\n      if (!printWindow) {\n        throw new Error('Pop-up blocked — allow pop-ups for this page in your browser and try again.');\n      }\n\n      const grouped = groupFunders(funders);\n      const genDate = new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });\n\n      const statusLines = STATUS_OPTIONS.filter((s) => statusCounts[s] > 0)\n        .map((s) => `<div>${escapeHtml(s)}: ${statusCounts[s]}</div>`)\n        .join('');\n\n      const funderBlocks = grouped\n        .map(({ name, rows }) => {\n          const total = rows.reduce((sum, r) => sum + parseAmount(r.amount), 0);\n          const statuses = [...new Set(rows.map((r) => r.status))].join(', ');\n          const headline =\n            rows.length > 1\n              ? `${escapeHtml(name)} — £${total.toLocaleString()} across ${rows.length} asks — ${escapeHtml(statuses)}`\n              : `${escapeHtml(name)} — ${escapeHtml(rows[0].amount)} — ${escapeHtml(rows[0].status)}`;\n          const subLines = rows\n            .map((r) => {\n              const bits = [r.appliesTo || 'General'];\n              if (rows.length > 1) bits.push(r.amount, r.status);\n              if (r.deadline) bits.push(`deadline: ${r.deadline}`);\n              if (r.url) bits.push(r.url);\n              return `<div class=\"subline\">• ${escapeHtml(bits.join(' — '))}</div>`;\n            })\n            .join('');\n          return `<div class=\"funder\"><div class=\"headline\">${headline}</div>${subLines}</div>`;\n        })\n        .join('');\n\n      const html = `<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<title>RSDG Funding Pipeline — Headlines Report</title>\n<style>\n  body { font-family: Arial, Helvetica, sans-serif; color: #0f2a3d; padding: 28px; }\n  h1 { color: ${COLORS.blue}; font-size: 19px; margin: 0 0 2px; }\n  .subtitle { font-weight: 700; font-size: 14px; margin-bottom: 2px; }\n  .meta { color: #5b7183; font-size: 11px; margin-bottom: 18px; }\n  .totals div { font-weight: 700; font-size: 13px; margin-bottom: 3px; }\n  h2 { color: ${COLORS.blue}; font-size: 13.5px; margin-top: 22px; margin-bottom: 8px; }\n  .funder { margin-bottom: 10px; }\n  .headline { font-weight: 700; font-size: 12.5px; }\n  .subline { font-size: 11px; color: #333; margin-left: 14px; }\n  @media print { body { padding: 10mm; } }\n</style>\n</head>\n<body>\n  <h1>Rothes Sports Development Group</h1>\n  <div class=\"subtitle\">Funding Pipeline — Headlines Report</div>\n  <div class=\"meta\">Generated ${genDate}</div>\n  <div class=\"totals\">\n    <div>Total identified across all funders: £${totalIdentified.toLocaleString()}+</div>\n    <div>Secured or awarded: £${totalSecured.toLocaleString()}</div>\n  </div>\n  <h2>By status</h2>\n  ${statusLines}\n  <h2>Funders</h2>\n  ${funderBlocks}\n</body>\n</html>`;\n\n      printWindow.document.open();\n      printWindow.document.write(html);\n      printWindow.document.close();\n      printWindow.focus();\n      // Give the new window a moment to lay out the content before invoking print.\n      setTimeout(() => {\n        printWindow.print();\n      }, 300);\n    } catch (err) {\n      console.error(err);\n      setPdfErrorDetail(err && err.message ? err.message : String(err));\n      setPdfStatus('error');\n    }\n  }\n\n  if (funders === null) {\n    return (\n      <div style={{ padding: 60, textAlign: 'center', color: COLORS.blue, fontWeight: 600 }}>\n        <Loader2 size={20} style={{ animation: 'spin 1s linear infinite' }} />\n        <div style={{ marginTop: 10 }}>Loading the funding pipeline…</div>\n        <style>{`@keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }`}</style>\n      </div>\n    );\n  }\n\n  const totalIdentified = funders.reduce((sum, f) => sum + parseAmount(f.amount), 0);\n  const totalSecured = funders.filter((f) => f.status === 'Secured' || f.status === 'Awarded').reduce((sum, f) => sum + parseAmount(f.amount), 0);\n  const statusCounts = STATUS_OPTIONS.reduce((acc, s) => ({ ...acc, [s]: funders.filter((f) => f.status === s).length }), {});\n\n  return (\n    <div style={{ maxWidth: 900, margin: '0 auto', padding: '0 24px 60px' }}>\n      <div\n        style={{\n          background: '#fff',\n          marginTop: -24,\n          borderRadius: 6,\n          boxShadow: '0 1px 3px rgba(0,60,90,0.12)',\n          padding: '28px',\n        }}\n      >\n        <h2 style={{ color: COLORS.blue, fontSize: 20, fontWeight: 800, margin: '0 0 4px' }}>Funding pipeline</h2>\n        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: 12, marginBottom: 20 }}>\n          <p style={{ color: '#5b7183', fontSize: 13.5, margin: 0, maxWidth: 520, fontWeight: 300 }}>\n            Shared across everyone who opens this tool. Seeded from the business plan; edit statuses and notes as things move.\n          </p>\n          <button onClick={handleDownloadPdf} style={{ ...ghostBtn, whiteSpace: 'nowrap' }}>\n            <Download size={15} />\n            Print headlines report (save as PDF)\n          </button>\n        </div>\n        {pdfStatus === 'error' && (\n          <div style={{ display: 'flex', gap: 8, color: '#b42318', fontSize: 13, marginBottom: 16 }}>\n            <AlertCircle size={16} style={{ flexShrink: 0, marginTop: 1 }} />\n            <span>\n              Couldn't build the PDF: <code style={{ fontFamily: 'monospace', fontSize: 12 }}>{pdfErrorDetail || 'unknown error'}</code>. Try again, or use Copy/Download on the table itself in the meantime.\n            </span>\n          </div>\n        )}\n\n        <div style={{ display: 'flex', gap: 24, flexWrap: 'wrap', marginBottom: 22, padding: '14px 18px', background: '#f7fafc', borderRadius: 6 }}>\n          <div>\n            <div style={{ fontSize: 12, color: '#5b7183', fontWeight: 700 }}>IDENTIFIED (ALL ROWS)</div>\n            <div style={{ fontSize: 20, color: COLORS.blue, fontWeight: 800 }}>£{totalIdentified.toLocaleString()}+</div>\n          </div>\n          <div>\n            <div style={{ fontSize: 12, color: '#5b7183', fontWeight: 700 }}>SECURED OR AWARDED</div>\n            <div style={{ fontSize: 20, color: COLORS.green, fontWeight: 800 }}>£{totalSecured.toLocaleString()}</div>\n          </div>\n          <div style={{ flex: 1, minWidth: 200 }}>\n            <div style={{ fontSize: 12, color: '#5b7183', fontWeight: 700, marginBottom: 6 }}>BY STATUS</div>\n            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>\n              {STATUS_OPTIONS.filter((s) => statusCounts[s] > 0).map((s) => (\n                <span\n                  key={s}\n                  style={{\n                    fontSize: 11.5,\n                    fontWeight: 700,\n                    color: '#fff',\n                    background: STATUS_COLORS[s],\n                    padding: '3px 9px',\n                    borderRadius: 20,\n                  }}\n                >\n                  {s} · {statusCounts[s]}\n                </span>\n              ))}\n            </div>\n          </div>\n        </div>\n\n        {loadError && (\n          <div style={{ display: 'flex', gap: 8, color: '#b42318', fontSize: 13, marginBottom: 16 }}>\n            <AlertCircle size={16} style={{ flexShrink: 0, marginTop: 1 }} />\n            Changes aren't saving right now: <code style={{ fontFamily: 'monospace', fontSize: 12 }}>{loadErrorDetail || 'no detail available'}</code>. They'll hold for this session but won't persist.\n          </div>\n        )}\n\n        <div style={{ overflowX: 'auto' }}>\n          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13.5, tableLayout: 'fixed' }}>\n            <colgroup>\n              <col style={{ width: '32%' }} />\n              <col style={{ width: '13%' }} />\n              <col style={{ width: '15%' }} />\n              <col style={{ width: '18%' }} />\n              <col style={{ width: '10%' }} />\n              <col style={{ width: '12%' }} />\n            </colgroup>\n            <thead>\n              <tr style={{ textAlign: 'left', borderBottom: `2px solid ${COLORS.blue}` }}>\n                <SortableHeader label=\"Funder\" sortKey=\"funder\" sortBy={sortBy} sortDir={sortDir} onSort={handleSort} />\n                <SortableHeader label=\"Amount\" sortKey=\"amount\" sortBy={sortBy} sortDir={sortDir} onSort={handleSort} />\n                <th style={{ padding: '8px 10px', color: COLORS.blue, fontWeight: 800, fontSize: 12 }}>Deadline</th>\n                <SortableHeader label=\"Status\" sortKey=\"status\" sortBy={sortBy} sortDir={sortDir} onSort={handleSort} />\n                <th style={{ padding: '8px 10px', color: COLORS.blue, fontWeight: 800, fontSize: 12 }}>Link</th>\n                <th style={{ padding: '8px 10px', color: COLORS.blue, fontWeight: 800, fontSize: 12 }}></th>\n              </tr>\n            </thead>\n            <tbody>\n              {(() => {\n                const grouped = groupFunders(funders);\n                if (sortBy) {\n                  grouped.sort((a, b) => {\n                    let cmp = 0;\n                    if (sortBy === 'funder') {\n                      cmp = a.name.localeCompare(b.name);\n                    } else if (sortBy === 'amount') {\n                      const totalA = a.rows.reduce((s, r) => s + parseAmount(r.amount), 0);\n                      const totalB = b.rows.reduce((s, r) => s + parseAmount(r.amount), 0);\n                      cmp = totalA - totalB;\n                    } else if (sortBy === 'status') {\n                      const idxA = Math.min(...a.rows.map((r) => STATUS_OPTIONS.indexOf(r.status)));\n                      const idxB = Math.min(...b.rows.map((r) => STATUS_OPTIONS.indexOf(r.status)));\n                      cmp = idxA - idxB;\n                    }\n                    return sortDir === 'asc' ? cmp : -cmp;\n                  });\n                }\n                return grouped;\n              })().map(({ name, rows }) => {\n                if (rows.length === 1) {\n                  return <FunderLine key={rows[0].id} f={rows[0]} expandedId={expandedId} setExpandedId={setExpandedId} updateRow={updateRow} deleteRow={deleteRow} />;\n                }\n                const isGroupOpen = !!expandedGroups[name];\n                const total = rows.reduce((sum, r) => sum + parseAmount(r.amount), 0);\n                const looksApprox = rows.some((r) => /[-–]|TBC/i.test(r.amount));\n                const statusSet = [...new Set(rows.map((r) => r.status))];\n                return (\n                  <React.Fragment key={name}>\n                    <tr style={{ borderBottom: isGroupOpen ? 'none' : '1px solid #eef2f5', background: '#fbfdfe' }}>\n                      <td style={{ padding: '8px 10px', fontWeight: 700, color: COLORS.ink, wordBreak: 'break-word' }}>\n                        {name} <span style={{ fontSize: 11, fontWeight: 700, color: '#94a3b8' }}>· {rows.length} asks</span>\n                      </td>\n                      <td style={{ padding: '8px 10px', color: COLORS.ink, wordBreak: 'break-word', fontWeight: 700 }}>\n                        £{total.toLocaleString()}\n                        {looksApprox ? '+' : ''} <span style={{ fontWeight: 400, color: '#94a3b8', fontSize: 11.5 }}>combined</span>\n                      </td>\n                      <td style={{ padding: '8px 10px', color: '#5b7183' }}>—</td>\n                      <td style={{ padding: '8px 10px' }}>\n                        <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>\n                          {statusSet.map((s) => (\n                            <span key={s} style={statusPillStyle(STATUS_COLORS[s])}>\n                              {s}\n                            </span>\n                          ))}\n                        </div>\n                      </td>\n                      <td style={{ padding: '8px 10px', textAlign: 'center', color: '#d7e1e8' }}>—</td>\n                      <td style={{ padding: '8px 10px' }}>\n                        <button\n                          onClick={() => toggleGroup(name)}\n                          title={isGroupOpen ? 'Hide the individual asks' : 'Show the individual asks'}\n                          style={{\n                            border: 'none',\n                            background: 'none',\n                            color: COLORS.blue,\n                            cursor: 'pointer',\n                            display: 'flex',\n                            alignItems: 'center',\n                            transform: isGroupOpen ? 'rotate(90deg)' : 'rotate(0deg)',\n                            transition: 'transform 0.15s ease',\n                          }}\n                        >\n                          <ChevronRight size={18} />\n                        </button>\n                      </td>\n                    </tr>\n                    {isGroupOpen &&\n                      rows.map((r) => (\n                        <FunderLine key={r.id} f={r} indent expandedId={expandedId} setExpandedId={setExpandedId} updateRow={updateRow} deleteRow={deleteRow} />\n                      ))}\n                  </React.Fragment>\n                );\n              })}\n            </tbody>\n          </table>\n        </div>\n\n        {showAdd ? (\n          <div style={{ marginTop: 20, padding: 16, background: '#f7fafc', borderRadius: 6, border: '1px solid #e2e8ee' }}>\n            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10, marginBottom: 10 }}>\n              <input style={inputStyle} placeholder=\"Funder name\" value={newFunder.name} onChange={(e) => setNewFunder({ ...newFunder, name: e.target.value })} />\n              <input style={inputStyle} placeholder=\"Amount (e.g. £10,000)\" value={newFunder.amount} onChange={(e) => setNewFunder({ ...newFunder, amount: e.target.value })} />\n              <input style={inputStyle} placeholder=\"Applies to\" value={newFunder.appliesTo} onChange={(e) => setNewFunder({ ...newFunder, appliesTo: e.target.value })} />\n              <input style={inputStyle} placeholder=\"Deadline, if there is one\" value={newFunder.deadline} onChange={(e) => setNewFunder({ ...newFunder, deadline: e.target.value })} />\n              <input\n                style={{ ...inputStyle, gridColumn: '1 / -1' }}\n                placeholder=\"URL (link to further information)\"\n                value={newFunder.url}\n                onChange={(e) => setNewFunder({ ...newFunder, url: e.target.value })}\n              />\n            </div>\n            <div style={{ display: 'flex', gap: 10 }}>\n              <button onClick={addRow} style={{ background: COLORS.orange, color: '#fff', border: 'none', borderRadius: 5, padding: '9px 18px', fontWeight: 700, fontSize: 13.5, cursor: 'pointer' }}>\n                Add funder\n              </button>\n              <button onClick={() => setShowAdd(false)} style={{ background: 'none', border: 'none', color: '#5b7183', fontWeight: 600, fontSize: 13.5, cursor: 'pointer' }}>\n                Cancel\n              </button>\n            </div>\n          </div>\n        ) : showBulkAdd ? (\n          <div style={{ marginTop: 20, padding: 18, background: '#f7fafc', borderRadius: 6, border: '1px solid #e2e8ee' }}>\n            {bulkStatus !== 'preview' && (\n              <React.Fragment>\n                <div style={{ fontWeight: 800, color: COLORS.blue, fontSize: 14, marginBottom: 10 }}>Bulk add funders</div>\n                <Field label=\"Paste funder information\" hint=\"Copy from a spreadsheet, an email, a GrantFinder or Localgiving export, anything. Any layout is fine.\">\n                  <textarea\n                    style={{ ...inputStyle, minHeight: 110, resize: 'vertical' }}\n                    value={bulkPasteText}\n                    onChange={(e) => setBulkPasteText(e.target.value)}\n                    placeholder=\"Paste rows, a list, or freeform notes here...\"\n                  />\n                </Field>\n                <Field label=\"Or upload a spreadsheet\" hint=\"xlsx, xls or csv. Can be used together with pasted text, or instead of it.\">\n                  <FileDrop label=\"Upload spreadsheet\" files={bulkFiles} setFiles={setBulkFiles} multiple={true} />\n                </Field>\n                <div style={{ display: 'flex', gap: 10, alignItems: 'center', marginTop: 4 }}>\n                  <button\n                    onClick={handleExtract}\n                    disabled={bulkStatus === 'extracting' || (!bulkPasteText.trim() && bulkFiles.length === 0)}\n                    style={{\n                      background: bulkStatus === 'extracting' ? '#cbd5df' : COLORS.orange,\n                      color: '#fff',\n                      border: 'none',\n                      borderRadius: 5,\n                      padding: '9px 18px',\n                      fontWeight: 700,\n                      fontSize: 13.5,\n                      cursor: bulkStatus === 'extracting' ? 'not-allowed' : 'pointer',\n                      display: 'flex',\n                      alignItems: 'center',\n                      gap: 8,\n                    }}\n                  >\n                    {bulkStatus === 'extracting' && <Loader2 size={15} style={{ animation: 'spin 1s linear infinite' }} />}\n                    {bulkStatus === 'extracting' ? 'Reading…' : 'Extract funders'}\n                  </button>\n                  <button onClick={cancelBulkAdd} style={{ background: 'none', border: 'none', color: '#5b7183', fontWeight: 600, fontSize: 13.5, cursor: 'pointer' }}>\n                    Cancel\n                  </button>\n                </div>\n                {bulkStatus === 'error' && (\n                  <div style={{ display: 'flex', gap: 8, alignItems: 'flex-start', color: '#b42318', fontSize: 13, marginTop: 14 }}>\n                    <AlertCircle size={16} style={{ flexShrink: 0, marginTop: 1 }} />\n                    {bulkErrorDetail}\n                  </div>\n                )}\n              </React.Fragment>\n            )}\n\n            {bulkStatus === 'preview' && (\n              <React.Fragment>\n                <div style={{ fontWeight: 800, color: COLORS.blue, fontSize: 14, marginBottom: 4 }}>\n                  Found {bulkPreview.length} funder{bulkPreview.length === 1 ? '' : 's'}\n                </div>\n                <p style={{ fontSize: 12.5, color: '#5b7183', margin: '0 0 14px', fontWeight: 300 }}>\n                  Check these over, untick anything wrong or unwanted, then add the rest. You can edit any detail afterwards in the table itself.\n                </p>\n                <div style={{ display: 'flex', flexDirection: 'column', gap: 8, maxHeight: 420, overflowY: 'auto', marginBottom: 14 }}>\n                  {bulkPreview.map((r) => (\n                    <label\n                      key={r._key}\n                      style={{\n                        display: 'flex',\n                        gap: 10,\n                        alignItems: 'flex-start',\n                        padding: '10px 12px',\n                        background: '#fff',\n                        border: `1px solid ${r.possibleDuplicate ? COLORS.orange : '#e2e8ee'}`,\n                        borderRadius: 6,\n                        cursor: 'pointer',\n                      }}\n                    >\n                      <input type=\"checkbox\" checked={r.include} onChange={() => toggleBulkInclude(r._key)} style={{ marginTop: 3 }} />\n                      <div style={{ flex: 1, minWidth: 0 }}>\n                        <div style={{ fontWeight: 700, color: COLORS.ink, fontSize: 13.5 }}>\n                          {r.name || '(no name found)'} {r.appliesTo && <span style={{ fontWeight: 400, color: '#5b7183' }}>· {r.appliesTo}</span>}\n                        </div>\n                        <div style={{ fontSize: 12, color: '#5b7183', marginTop: 2 }}>\n                          {r.amount} {r.deadline && `· deadline: ${r.deadline}`}\n                        </div>\n                        {r.notes && <div style={{ fontSize: 12, color: COLORS.ink, marginTop: 4 }}>{r.notes}</div>}\n                        {r.possibleDuplicate && (\n                          <div style={{ fontSize: 11.5, color: COLORS.orange, fontWeight: 700, marginTop: 4 }}>\n                            A funder with this exact name is already in your pipeline, check before adding a second entry.\n                          </div>\n                        )}\n                      </div>\n                    </label>\n                  ))}\n                </div>\n                <div style={{ display: 'flex', gap: 10 }}>\n                  <button\n                    onClick={confirmBulkAdd}\n                    disabled={!bulkPreview.some((r) => r.include)}\n                    style={{\n                      background: bulkPreview.some((r) => r.include) ? COLORS.orange : '#cbd5df',\n                      color: '#fff',\n                      border: 'none',\n                      borderRadius: 5,\n                      padding: '9px 18px',\n                      fontWeight: 700,\n                      fontSize: 13.5,\n                      cursor: bulkPreview.some((r) => r.include) ? 'pointer' : 'not-allowed',\n                    }}\n                  >\n                    Add {bulkPreview.filter((r) => r.include).length} to the pipeline\n                  </button>\n                  <button onClick={cancelBulkAdd} style={{ background: 'none', border: 'none', color: '#5b7183', fontWeight: 600, fontSize: 13.5, cursor: 'pointer' }}>\n                    Cancel\n                  </button>\n                </div>\n              </React.Fragment>\n            )}\n          </div>\n        ) : (\n          <div style={{ display: 'flex', gap: 10, marginTop: 18, flexWrap: 'wrap' }}>\n            <button\n              onClick={() => setShowAdd(true)}\n              style={{\n                background: 'none',\n                border: `1.5px solid ${COLORS.blue}`,\n                color: COLORS.blue,\n                borderRadius: 5,\n                padding: '9px 18px',\n                fontWeight: 700,\n                fontSize: 13.5,\n                cursor: 'pointer',\n              }}\n            >\n              + Add a funder not on this list\n            </button>\n            <button\n              onClick={() => setShowBulkAdd(true)}\n              style={{\n                background: 'none',\n                border: `1.5px solid ${COLORS.blue}`,\n                color: COLORS.blue,\n                borderRadius: 5,\n                padding: '9px 18px',\n                fontWeight: 700,\n                fontSize: 13.5,\n                cursor: 'pointer',\n              }}\n            >\n              Bulk add funders\n            </button>\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n\n\n/* ---------------- App shell with tabs ---------------- */\n\nconst VIEW_COPY = {\n  bid: {\n    title: 'Bid Builder',\n    subtitle:\n      \"This already knows the business plan, the board and the finances. Just tell it about this specific bid, and it'll draft the application, flagging anything it can't back up rather than making it up.\",\n  },\n  pipeline: {\n    title: 'Funding Pipeline',\n    subtitle: 'Every funder in one shared table. Track status, deadlines and notes as things move.',\n  },\n};\n\nfunction App() {\n  const [view, setView] = useState('bid');\n  const copy = VIEW_COPY[view];\n  return (\n    <div style={{ fontFamily: \"'Nunito Sans', system-ui, sans-serif\", background: '#eef4f8', minHeight: '100%' }}>\n      <div style={{ position: 'relative', background: COLORS.blue, overflow: 'hidden', padding: '22px 24px 0' }}>\n        <div\n          style={{\n            position: 'absolute',\n            right: 0,\n            top: '55%',\n            bottom: 0,\n            width: '30%',\n            background: COLORS.orange,\n            clipPath: 'polygon(55% 0, 100% 0, 100% 100%, 15% 100%)',\n          }}\n        />\n        <div\n          style={{\n            position: 'absolute',\n            right: 0,\n            bottom: 0,\n            height: 8,\n            width: '100%',\n            background: COLORS.yellow,\n          }}\n        />\n        <div style={{ position: 'relative', maxWidth: 900, margin: '0 auto' }}>\n          <div style={{ color: COLORS.yellow, fontWeight: 700, fontSize: 13, letterSpacing: 0.3, marginBottom: 6 }}>\n            Rothes Sports Development Group\n          </div>\n          <h1 style={{ color: '#fff', fontSize: 28, fontWeight: 800, margin: 0, lineHeight: 1.2, maxWidth: 460 }}>{copy.title}</h1>\n          <p style={{ color: '#dfeaf3', fontSize: 14, lineHeight: 1.5, marginTop: 8, marginBottom: 18, maxWidth: 420, minHeight: 84, fontWeight: 300 }}>{copy.subtitle}</p>\n          <div style={{ display: 'flex', gap: 4 }}>\n            {[\n              { key: 'bid', label: 'Bid builder' },\n              { key: 'pipeline', label: 'Funding pipeline' },\n            ].map((tab) => (\n              <button\n                key={tab.key}\n                onClick={() => setView(tab.key)}\n                style={{\n                  background: view === tab.key ? '#fff' : 'rgba(255,255,255,0.14)',\n                  color: view === tab.key ? COLORS.blueDark : '#eaf2f7',\n                  border: 'none',\n                  borderRadius: '6px 6px 0 0',\n                  padding: '9px 20px',\n                  fontWeight: 700,\n                  fontSize: 13.5,\n                  cursor: 'pointer',\n                }}\n              >\n                {tab.label}\n              </button>\n            ))}\n          </div>\n        </div>\n      </div>\n      {view === 'bid' ? <BidBuilder /> : <PipelineTracker />}\n    </div>\n  );\n}\n\n\nReactDOM.createRoot(document.getElementById('root')).render(<App />);\n</script>\n</body>\n</html>\n";

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (url.pathname === '/api/draft' && request.method === 'POST') {
      return handleDraft(request, env);
    }

    if (url.pathname === '/api/pipeline') {
      return handlePipeline(request, env);
    }

    return new Response(PAGE_HTML, {
      headers: { 'content-type': 'text/html;charset=UTF-8' },
    });
  },
};

async function handleDraft(request, env) {
  try {
    // Safe diagnostic: never logs or returns the real key, only whether it's
    // present, how long it is, and its first/last few characters, enough to
    // confirm it actually reached the Worker without exposing it again.
    const key = env.ANTHROPIC_API_KEY;
    const keyInfo = key
      ? `present, length ${key.length}, starts "${key.slice(0, 12)}", ends "${key.slice(-4)}"`
      : 'MISSING — env.ANTHROPIC_API_KEY is empty or undefined';

    // Force streaming on the outgoing request, regardless of what the client
    // sent. A long generation (the review pass especially, with its full
    // knowledge base plus the whole draft) can take long enough that
    // Cloudflare's own edge gives up waiting for a single, all-at-once
    // response (a 524). Streaming keeps data flowing continuously instead,
    // which avoids that entirely.
    const bodyJson = JSON.parse(await request.text());
    bodyJson.stream = true;

    const anthropicResponse = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'x-api-key': key,
        'anthropic-version': '2023-06-01',
      },
      body: JSON.stringify(bodyJson),
    });

    if (!anthropicResponse.ok) {
      // A failure here happens before streaming starts, so this is still a
      // normal, small, fast JSON error body, safe to read in full.
      const data = await anthropicResponse.text();
      let parsed;
      try {
        parsed = JSON.parse(data);
      } catch (e) {
        parsed = { raw: data };
      }
      parsed._keyDiagnostic = keyInfo;
      return new Response(JSON.stringify(parsed), {
        status: anthropicResponse.status,
        headers: { 'content-type': 'application/json' },
      });
    }

    // Success: relay Anthropic's stream straight through to the browser
    // without buffering it here. The app on the other end reads this as
    // server-sent events and assembles the text itself.
    return new Response(anthropicResponse.body, {
      status: anthropicResponse.status,
      headers: { 'content-type': 'text/event-stream; charset=utf-8' },
    });
  } catch (err) {
    return new Response(JSON.stringify({ error: 'Proxy error', detail: String(err) }), {
      status: 500,
      headers: { 'content-type': 'application/json' },
    });
  }
}

async function handlePipeline(request, env) {
  const KEY = 'funders';

  if (request.method === 'GET') {
    try {
      const value = await env.PIPELINE_KV.get(KEY);
      return new Response(JSON.stringify({ value: value || null }), {
        headers: { 'content-type': 'application/json' },
      });
    } catch (err) {
      return new Response(JSON.stringify({ error: 'Load failed', detail: String(err) }), {
        status: 500,
        headers: { 'content-type': 'application/json' },
      });
    }
  }

  if (request.method === 'POST') {
    try {
      const { value } = await request.json();
      await env.PIPELINE_KV.put(KEY, value);
      return new Response(JSON.stringify({ ok: true }), {
        headers: { 'content-type': 'application/json' },
      });
    } catch (err) {
      return new Response(JSON.stringify({ error: 'Save failed', detail: String(err) }), {
        status: 500,
        headers: { 'content-type': 'application/json' },
      });
    }
  }

  return new Response('Method not allowed', { status: 405 });
}
